@use_kernel_forward_from_hub("RMSNorm")
class ShensiVlRMSNorm(nn.Module):
    def __init__(self, hidden_size, eps: float = 1e-6) -> None:
        """
        ShensiVlRMSNorm is equivalent to T5LayerNorm
        """
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        input_dtype = hidden_states.dtype
        hidden_states = hidden_states.to(torch.float32)
        variance = hidden_states.pow(2).mean(-1, keepdim=True)
        hidden_states = hidden_states * torch.rsqrt(variance + self.variance_epsilon)
        return self.weight * hidden_states.to(input_dtype)

    def extra_repr(self):
        return f"{tuple(self.weight.shape)}, eps={self.variance_epsilon}"


class ShensiVlUnweightedRMSNorm(nn.Module):
    def __init__(self, eps: float = 1.0e-6):
        super().__init__()
        self.eps = eps

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return x * torch.rsqrt(x.float().square().mean(-1, keepdim=True) + self.eps).to(x.dtype)


class ShensiVlRotaryEmbedding(nn.Module):
    """
    Multi-layer-type rotary embedding (Laguna pattern: partial rotary on top of
    Gemma3's per-layer-type buffers), specialised for V4's *interleaved* RoPE.
    Interleaved RoPE: one `θ_i` per pair (`rope_head_dim // 2` entries),
    DIFF no end-to-end duplication. Same shape as `inv_freq @ position_ids`.

    V4 deliberately decouples its architecture `layer_types`
    (`sliding_attention` / `compressed_sparse_attention` /
    `heavily_compressed_attention`) from its rope-type labels (`main` /
    `compress`) — the latter live as keys in `config.rope_parameters` and
    only differ in their `rope_theta` base. So this override replaces
    Laguna's `set(config.layer_types)` iteration with `rope_parameters.keys()`
    when building the per-type inv_freq buffers.
    """

    @deprecate_kwarg("device", version="5.18")
    def __init__(self, config: ShensiVlConfig, device=None):
        super().__init__()
        self.max_seq_len_cached = config.max_position_embeddings
        self.original_max_seq_len = config.max_position_embeddings
        self.config = config
        # Only the nested per-rope-type sub-dicts are real layer types — the top-level
        # `rope_type` key that ``convert_rope_params_to_dict`` may leave on
        # ``config.rope_parameters`` is a flat-shape leftover, not a layer.
        self.layer_types = [k for k, v in config.rope_parameters.items() if isinstance(v, dict)]
        self.rope_type = {}
        for layer_type in self.layer_types:
            rope_params = config.rope_parameters[layer_type]
            self.rope_type[layer_type] = rope_params["rope_type"]
            rope_init_fn = self.compute_default_rope_parameters
            if self.rope_type[layer_type] != "default":
                rope_init_fn = ROPE_INIT_FUNCTIONS[self.rope_type[layer_type]]
            inv_freq, attention_scaling = rope_init_fn(config, device, layer_type=layer_type)
            setattr(self, f"{layer_type}_inv_freq", nn.Buffer(inv_freq, persistent=False))
            setattr(self, f"{layer_type}_original_inv_freq", nn.Buffer(inv_freq.clone(), persistent=False))
            setattr(self, f"{layer_type}_attention_scaling", attention_scaling)

    @staticmethod
    @deprecate_kwarg("device", version="5.18")
    def compute_default_rope_parameters(
        config: ShensiVlConfig, device=None, layer_type: str | None = None, **kwargs
    ) -> tuple[torch.Tensor, float]:
        """
        Computes the inverse frequencies according to the original RoPE implementation
        Args:
            config ([`~transformers.PreTrainedConfig`]):
                The model configuration.
            layer_type (`str`, *optional*):
                The current layer type if the model has different RoPE parameters per type.
                Should not be used unless `config.layer_types is not None`
        Returns:
            Tuple of (`torch.Tensor`, `float`), containing the inverse frequencies for the RoPE embeddings and the
            post-processing scaling factor applied to the computed cos/sin (unused in this type of RoPE).
        """
        base = config.rope_parameters[layer_type]["rope_theta"]
        # key difference to gemma3: partial rope
        partial_rotary_factor = config.rope_parameters[layer_type].get("partial_rotary_factor", 1.0)
        head_dim = getattr(config, "head_dim", None) or config.hidden_size // config.num_attention_heads
        dim = int(head_dim * partial_rotary_factor)

        attention_factor = 1.0  # Unused in this type of RoPE

        # Compute the inverse frequencies
        inv_freq = 1.0 / (base ** (torch.arange(0, dim, 2, dtype=torch.float) / dim))
        return inv_freq.to(device), attention_factor

    @torch.no_grad()
    @dynamic_rope_update  # power user: used with advanced RoPE types (e.g. dynamic rope)
    def forward(self, x, position_ids, layer_type=None):
        # Key difference vs Laguna's forward: no `torch.cat([freqs, freqs], dim=-1)`
        # duplication. V4's interleaved RoPE pairs consecutive channels, so we only need
        # `rope_head_dim // 2` unique θ entries — the `apply_rotary_pos_emb` helper does
        # the `repeat_interleave(2)` next to the rotation math, where the link between
        # the doubled dim and `rotate_half` is local and obvious.
        inv_freq = getattr(self, f"{layer_type}_inv_freq")
        attention_scaling = getattr(self, f"{layer_type}_attention_scaling")
        inv_freq_expanded = inv_freq[None, :, None].float().expand(position_ids.shape[0], -1, 1).to(x.device)
        position_ids_expanded = position_ids[:, None, :].float()
        device_type = x.device.type if isinstance(x.device.type, str) and x.device.type != "mps" else "cpu"
        with maybe_autocast(device_type=device_type, enabled=False):
            freqs = (inv_freq_expanded.float() @ position_ids_expanded.float()).transpose(1, 2)
            cos = freqs.cos() * attention_scaling
            sin = freqs.sin() * attention_scaling
        return cos.to(dtype=x.dtype), sin.to(dtype=x.dtype)


class ShensiVlHCACache(DynamicSlidingWindowLayer):
    r"""Cache layer for HCA blocks (paper §2.3.2). Holds the long-range compressor's
    buffer / running compressed entries / count on top of the sliding-window K=V
    branch. HCA uses *non-overlapping* windows, so there is *no* overlap state,
    and HCA has *no* indexer either.

    State is dict-keyed by entry name — HCA only uses `"compressor"`, but
    :class:`ShensiVlCSACache` adds `"indexer"` to the same dicts so a single
    set of methods (`store_compression_weights` / `update_compressor_states`)
    serves both:

      * `compressed_kv[name]` — the running list of compressed KV entries
        emitted so far (one every `compress_rate` source tokens; the long-range
        KVs the attention concatenates onto its sliding-window keys / values).
      * `buffer_kv[name]` / `buffer_gate[name]` — source tokens that arrived
        between two full windows; once the buffer hits `compress_rate` tokens
        the compressor closes a window, emits one entry, and drains the buffer.
      * `entry_count[name]` — number of compressed entries emitted so far, so
        `entry_count[name] * compress_rate` is the absolute position of the
        *next* window's first source token. Tracked separately from
        `position_ids` so prefill -> decode -> prefill stays consistent.
    """

    _layer_type = "heavily_compressed_attention"

    def __init__(self, config: "ShensiVlConfig", **kwargs):
        super().__init__(sliding_window=config.sliding_window)
        self.compress_rate = config.compress_rates["heavily_compressed_attention"]
        self.buffer_kv: dict[str, torch.Tensor | None] = {"compressor": None}
        self.buffer_gate: dict[str, torch.Tensor | None] = {"compressor": None}
        self.compressed_kv: dict[str, torch.Tensor | None] = {"compressor": None}
        self.entry_count: dict[str, int] = {"compressor": 0}

    def update(self, key_states: torch.Tensor, value_states: torch.Tensor, *args, **kwargs):
        """
        Shared sliding-window K=V update body. V4 uses shared-KV MQA, so `keys` and
        `values` point to the same storage on every layer.
        """
        if not self.is_initialized:
            self.lazy_initialization(key_states, value_states)
            self.values = self.keys
        self.cumulative_length += key_states.shape[-2]
        full = torch.cat([self.keys, key_states], dim=-2)
        self.keys = full[:, :, -self.sliding_window + 1 :, :]
        self.values = self.keys
        return full, full

    def store_compression_weights(
        self, name: str, kv: torch.Tensor, gate: torch.Tensor
    ) -> tuple[torch.Tensor, torch.Tensor, int]:
        r"""
        Concatenate the new projected `(kv, gate)` (paper §2.3.2 eqs. 20–21:
        `C = H·W^{KV}`, `Z = H·W^Z`) for entry `name` with what's already in
        the buffer, peel off the longest window-aligned prefix (the chunk
        ready to compress), keep the leftover in the buffer for next call,
        and return `(chunk_kv, chunk_gate, first_window_position)`. The
        returned chunk is softmax-aggregated by the compressor with
        `position_bias` to emit one compressed entry per window of
        `compress_rate` tokens.
        """
        first_window_position = self.entry_count[name] * self.compress_rate
        buffered_kv, buffered_gate = self.buffer_kv[name], self.buffer_gate[name]
        if buffered_kv is not None and buffered_kv.shape[1]:
            kv = torch.cat([buffered_kv, kv], dim=1)
            gate = torch.cat([buffered_gate, gate], dim=1)
        # only return the longest prefix that's a multiple of compress_rate; the rest stays in the buffer for next time
        usable = (kv.shape[1] // self.compress_rate) * self.compress_rate
        self.buffer_kv[name], self.buffer_gate[name] = kv[:, usable:], gate[:, usable:]
        return kv[:, :usable], gate[:, :usable], first_window_position

    def update_compressor_states(self, name: str, compressed: torch.Tensor) -> torch.Tensor:
        r"""
        Append freshly emitted compressed entries to `compressed_kv[name]`
        (`C^{Comp}`, paper §2.3.2 eq. 23), bump `entry_count[name]`, and
        return the running `compressed_kv[name]`.
        """
        if self.compressed_kv[name] is None:
            self.compressed_kv[name] = compressed
        elif compressed.shape[1] > 0:
            self.compressed_kv[name] = torch.cat([self.compressed_kv[name], compressed], dim=1)
        self.entry_count[name] += compressed.shape[1]
        return self.compressed_kv[name]


class ShensiVlCSACache(ShensiVlHCACache):
    r"""Cache layer for CSA blocks (paper §2.3.1). Extends :class:`ShensiVlHCACache`
    by adding an `"indexer"` entry to the inherited `buffer_kv` / `buffer_gate` /
    `compressed_kv` / `entry_count` dicts, plus per-name *overlap* state for the
    two-series window scheme.

    What "overlap" means here: the CSA `kv_proj` / `gate_proj` produce `2 * head_dim`
    features per source token — two independent compressed series Ca and Cb stored
    in one tensor. Ca occupies `[..., :head_dim]`, Cb occupies `[..., head_dim:]`.
    Pooled entry `w` is the softmax-gated convex combination of window `w-1`'s Ca
    slice with window `w`'s Cb slice — effective width `2 * compress_rate_csa`,
    stride `compress_rate_csa` (paper §2.3.1).

    Because adjacent windows share state only through *the previous window's Ca
    slice*, the only thing we need to carry across a forward boundary is
    `chunk[:, -1, :, :head_dim]` (Ca) of the last full window — Cb is never read
    again. That's what `overlap_kv[name]` / `overlap_gate[name]` persist.
    """

    _layer_type = "compressed_sparse_attention"

    def __init__(self, config: "ShensiVlConfig", **kwargs):
        super().__init__(config)
        self.compress_rate = config.compress_rates["compressed_sparse_attention"]
        self.buffer_kv["indexer"] = None
        self.buffer_gate["indexer"] = None
        self.compressed_kv["indexer"] = None
        self.entry_count["indexer"] = 0
        self.overlap_kv: dict[str, torch.Tensor | None] = {"compressor": None, "indexer": None}
        self.overlap_gate: dict[str, torch.Tensor | None] = {"compressor": None, "indexer": None}

    def update_overlap_state(
        self, name: str, chunk_kv: torch.Tensor, chunk_gate: torch.Tensor, head_dim: int
    ) -> tuple[torch.Tensor | None, torch.Tensor | None]:
        r"""
        Read the `name` entry's prior window's Ca slice (saved on the previous
        forward call) and persist the *current* call's last-window Ca slice for
        the next call. Only the `:head_dim` slice (Ca) is ever consumed
        downstream — Cb has already been folded into the previous window's
        emitted compressed entry — so we store half what `chunk[:, -1]` holds.
        Returns `(prior_kv, prior_gate)` — both `None` on the very first call.
        """
        prior_kv, prior_gate = self.overlap_kv[name], self.overlap_gate[name]
        self.overlap_kv[name] = chunk_kv[:, -1, :, :head_dim].clone()
        self.overlap_gate[name] = chunk_gate[:, -1, :, :head_dim].clone()
        return prior_kv, prior_gate


class ShensiVlGroupedLinear(nn.Linear):
    """Block-diagonal grouped linear used by the grouped output projection
    The core attention's stacked output is `num_attention_heads* head_dim`-dim,
    which is *very* large (V4-Flash: 32768; V4-Pro: 65536). A direct
    `num_attention_heads*head_dim → hidden_size` projection would dominate the per-token cost.

    The paper sidesteps that by splitting the heads into `g` groups, projecting
    each `num_attention_heads * head_dim/g`-dim group independently to a `d_g`-dim intermediate output
    (with `d_g < num_attention_heads * head_dim/g`), and then mixing the resulting `g·d_g` vector to
    `hidden_size` through a single follow-up linear (`self_attn.o_b_proj`). This
    module owns the per-group block (`self_attn.o_a_proj`).

    For V4-Flash (num_attention_heads=64, head_dim=512, o_groups=8, o_lora_rank=1024,
    hidden_size=4096), g=8 groups of 4096-dim each are projected to 1024-dim, then
    mixed to 4096-dim; for V4-Pro (num_attention_heads=128, head_dim=512, o_groups=16,
    o_lora_rank=1024, hidden_size=7168), g=16 groups of 4096-dim each are projected
    to 1024-dim, then mixed to 7168-dim.
    """

    def __init__(self, in_features_per_group: int, out_features: int, n_groups: int, bias: bool = False):
        super().__init__(in_features_per_group, out_features, bias=bias)
        self.n_groups = n_groups

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        input_shape = x.shape[:-2]
        hidden_dim = x.shape[-1]
        w = self.weight.view(self.n_groups, -1, hidden_dim).transpose(1, 2)
        x = x.reshape(-1, self.n_groups, hidden_dim).transpose(0, 1)
        y = torch.bmm(x, w).transpose(0, 1)
        return y.reshape(*input_shape, self.n_groups, -1)


def rotate_half(x):
    """Rotates half the hidden dims of the input."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb(
    x: torch.Tensor, cos: torch.Tensor, sin: torch.Tensor, unsqueeze_dim: int = 1
) -> torch.Tensor:
    """V4 interleaved RoPE applied to the *trailing* rope slice of `x`.

    `cos` / `sin` come in half-sized (one entry per interleaved pair, from
    `ShensiVlRotaryEmbedding`); we expand them to the full rope dim with
    `repeat_interleave`, then rotate the last `2 * cos.shape[-1]` channels of `x`
    with the standard `x*cos + rotate_half(x)*sin` formula in fp32 and leave the
    leading nope channels untouched. V4-Flash lays each head out as `[nope | rope]`,
    matching the reference's `x[..., -rd:]` indexing.
    """
    cos = cos.repeat_interleave(2, dim=-1).unsqueeze(unsqueeze_dim)
    sin = sin.repeat_interleave(2, dim=-1).unsqueeze(unsqueeze_dim)
    rope_dim = cos.shape[-1]
    nope, rope = x[..., :-rope_dim], x[..., -rope_dim:]
    rotated = ((rope.float() * cos) + (rotate_half(rope).float() * sin)).to(x.dtype)
    return torch.cat([nope, rotated], dim=-1)


class ShensiVlHCACompressor(nn.Module):
    """
    Heavily Compressed Attention compressor (paper §2.3.2, eqs. 20–23). compresses
    every `compress_rate_hca` (m'=128) source tokens into a single compressed KV
    entry.

    Each closed window of m' tokens produces one compressed entry:
    `C^{Comp}_i = Σ_{j∈window} softmax(Z_j + B)_j ⊙ C_j`. RoPE on the trailing
    `rope_head_dim` slice is applied at the deterministic absolute position
    `i * compress_rate_hca + first_window_position` so cross-call concatenation
    stays causality-correct. Returns the running list of *all* compressed
    entries emitted so far (shape `[B, 1, T, head_dim]` with
    `T = entry_count["compressor"]`), so the attention can attend over the
    full long-range history.

    When `past_key_values is None` runs in stateless single-shot mode: compress
    every complete window from `hidden_states` and discard the remainder
    (instead of caching it).
    """

    rope_layer_type = "compress"

    def __init__(self, config: ShensiVlConfig):
        super().__init__()
        self.compress_rate = config.compress_rates["heavily_compressed_attention"]
        self.head_dim = config.head_dim
        self.kv_proj = nn.Linear(config.hidden_size, self.head_dim, bias=False)
        self.gate_proj = nn.Linear(config.hidden_size, self.head_dim, bias=False)
        self.position_bias = nn.Parameter(torch.empty(self.compress_rate, self.head_dim))
        self.kv_norm = ShensiVlRMSNorm(self.head_dim, eps=config.rms_norm_eps)
        self.rotary_emb = ShensiVlRotaryEmbedding(config)

    def forward(
        self,
        hidden_states: torch.Tensor,
        q_residual: torch.Tensor,
        position_ids: torch.Tensor,
        past_key_values: Cache | None,
        layer_idx: int,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        batch, _, _ = hidden_states.shape
        cache_layer: ShensiVlHCACache = past_key_values.layers[layer_idx] if past_key_values is not None else None
        kv = self.kv_proj(hidden_states)
        gate = self.gate_proj(hidden_states)
        if cache_layer is None:
            usable = (kv.shape[1] // self.compress_rate) * self.compress_rate
            chunk_kv, chunk_gate, first_window_position = kv[:, :usable], gate[:, :usable], 0
        else:
            chunk_kv, chunk_gate, first_window_position = cache_layer.store_compression_weights("compressor", kv, gate)

        if chunk_kv.shape[1] > 0:  # there were at least self.compress_rate tokens
            n_windows = chunk_kv.shape[1] // self.compress_rate
            chunk_kv = chunk_kv.view(batch, n_windows, self.compress_rate, -1)
            chunk_gate = chunk_gate.view(batch, n_windows, self.compress_rate, -1) + self.position_bias
            compressed = self.kv_norm(
                (chunk_kv * chunk_gate.softmax(dim=2, dtype=torch.float32).to(chunk_kv.dtype)).sum(dim=2)
            )
            positions = torch.arange(n_windows, device=compressed.device)
            positions = (positions * self.compress_rate + first_window_position).unsqueeze(0).expand(batch, -1)
            cos, sin = self.rotary_emb(compressed, position_ids=positions, layer_type=self.rope_layer_type)
            compressed = apply_rotary_pos_emb(compressed.unsqueeze(1), cos, sin).squeeze(1)
        else:
            compressed = chunk_kv.new_zeros((batch, 0, self.head_dim))

        if cache_layer is not None:
            compressed = cache_layer.update_compressor_states("compressor", compressed)
        compressed_kv = compressed.unsqueeze(1)

        compressed_len = compressed_kv.shape[2]
        seq_len = position_ids.shape[1]
        if seq_len == 1 or compressed_len == 0:
            return compressed_kv, None

        # query `t` may only see cache entries at pos `w` t > w * compress_rate (ex: t=7, w=2 t does not attend to it).
        entry_indices = torch.arange(compressed_len, device=compressed_kv.device)
        causal_threshold = (position_ids + 1) // self.compress_rate  # [B, S]
        block_bias = compressed_kv.new_zeros((batch, 1, seq_len, compressed_len))
        block_bias = block_bias.masked_fill(
            entry_indices.view(1, 1, 1, -1) >= causal_threshold.unsqueeze(1).unsqueeze(-1),
            float("-inf"),
        )
        return compressed_kv, block_bias


class ShensiVlIndexerScorer(nn.Module):
    r"""Lightning-indexer scoring head: `∑_h w_{t,h} · ReLU(q_{t,h} · K^IComp_s)`."""

    def __init__(self, config: ShensiVlConfig):
        super().__init__()
        self.softmax_scale = config.index_head_dim**-0.5
        self.weights_scaling = config.index_n_heads**-0.5
        self.weights_proj = nn.Linear(config.hidden_size, config.index_n_heads, bias=False)

    def forward(self, q: torch.Tensor, compressed_kv: torch.Tensor, hidden_states: torch.Tensor) -> torch.Tensor:
        scores = torch.matmul(q.float(), compressed_kv.transpose(-1, -2).float().unsqueeze(1))  # [B, S, H, T]
        scores = F.relu(scores) * self.softmax_scale
        weights = self.weights_proj(hidden_states).float() * self.weights_scaling  # [B, S, H]
        return (scores * weights.unsqueeze(-1)).sum(dim=2)  # [B, S, T]


class ShensiVlIndexer(nn.Module):
    r"""Lightning Indexer (paper §2.3.1, eqs. 13–17). Used by Compressed Sparse
    Attention (CSA) to pick the top-`k` compressed KV blocks per query, with
    `k = config.index_topk`. Each query then attends only to those `k` of the
    `seq_len / compress_rate_csa` compressed entries — reduction factor
    `(seq_len / compress_rate_csa) / index_topk` over full attention against
    the entire compressed sequence.

    The indexer runs its own scaled-down compressor at `index_head_dim` over
    the same windows as the outer CSA compressor, then scores queries against
    the compressed keys with `∑_h w_{t,h} · ReLU(q_{t,h} · K^IComp_s)` and
    keeps the top `index_topk` indices.

    The indexer has its own rotary because it applies RoPE to two sets of
    tensors:

      * *compressed keys* at deterministic positions
        `i * compress_rate + first_window_position`,
      * *queries* at the model's current `position_ids` (variable per forward).

    Both must use the same theta as the outer compressor
    (`compress_rope_theta`) so query/key inner products are
    translation-invariant — if they used different thetas, `q · k` would carry
    a residual position-dependent skew. We can't precompute cos/sin once at
    init because the query positions vary per call, so the indexer owns its
    own rotary and calls it twice per forward (once for compressed keys, once
    for queries) with `layer_type=self.rope_layer_type` (always `"compress"`).
    """

    rope_layer_type = "compress"

    def __init__(self, config: ShensiVlConfig):
        super().__init__()
        self.compress_rate = config.compress_rates["compressed_sparse_attention"]
        self.num_heads = config.index_n_heads
        self.head_dim = config.index_head_dim
        self.index_topk = config.index_topk
        self.kv_proj = nn.Linear(config.hidden_size, 2 * self.head_dim, bias=False)
        self.gate_proj = nn.Linear(config.hidden_size, 2 * self.head_dim, bias=False)
        self.position_bias = nn.Parameter(torch.empty(self.compress_rate, 2 * self.head_dim))
        self.kv_norm = ShensiVlRMSNorm(self.head_dim, eps=config.rms_norm_eps)
        self.q_b_proj = nn.Linear(config.q_lora_rank, self.num_heads * self.head_dim, bias=False)
        self.rotary_emb = ShensiVlRotaryEmbedding(config)
        self.scorer = ShensiVlIndexerScorer(config)

    def forward(
        self,
        hidden_states: torch.Tensor,
        q_residual: torch.Tensor,
        position_ids: torch.Tensor,
        past_key_values: Cache | None,
        layer_idx: int,
    ) -> torch.LongTensor:
        batch, seq_len, _ = hidden_states.shape
        cache_layer: ShensiVlCSACache | None = (
            past_key_values.layers[layer_idx] if past_key_values is not None else None
        )
        kv = self.kv_proj(hidden_states)
        gate = self.gate_proj(hidden_states)

        if cache_layer is None:
            usable = (kv.shape[1] // self.compress_rate) * self.compress_rate
            chunk_kv, chunk_gate, first_window_position = kv[:, :usable], gate[:, :usable], 0
        else:
            chunk_kv, chunk_gate, first_window_position = cache_layer.store_compression_weights("indexer", kv, gate)

        if chunk_kv.shape[1] > 0:
            n_windows = chunk_kv.shape[1] // self.compress_rate
            ratio = self.compress_rate
            chunk_kv = chunk_kv.view(batch, n_windows, ratio, -1)
            chunk_gate = chunk_gate.view(batch, n_windows, ratio, -1) + self.position_bias

            # Same Ca / Cb overlap layout as the outer CSA compressor, at index_head_dim.
            new_kv = chunk_kv.new_zeros((batch, n_windows, 2 * ratio, self.head_dim))
            new_gate = chunk_gate.new_full((batch, n_windows, 2 * ratio, self.head_dim), float("-inf"))
            new_kv[:, :, ratio:] = chunk_kv[..., self.head_dim :]
            new_gate[:, :, ratio:] = chunk_gate[..., self.head_dim :]
            if n_windows > 1:
                new_kv[:, 1:, :ratio] = chunk_kv[:, :-1, :, : self.head_dim]
                new_gate[:, 1:, :ratio] = chunk_gate[:, :-1, :, : self.head_dim]
            if cache_layer is not None:
                prior_kv, prior_gate = cache_layer.update_overlap_state("indexer", chunk_kv, chunk_gate, self.head_dim)
                if prior_kv is not None:
                    new_kv[:, 0, :ratio] = prior_kv.to(new_kv.dtype)
                    new_gate[:, 0, :ratio] = prior_gate.to(new_gate.dtype)

            compressed = self.kv_norm(
                (new_kv * new_gate.softmax(dim=2, dtype=torch.float32).to(new_kv.dtype)).sum(dim=2)
            )
            positions = torch.arange(n_windows, device=compressed.device)
            positions = positions * self.compress_rate + first_window_position
            positions = positions.unsqueeze(0).expand(batch, -1)
            cos, sin = self.rotary_emb(compressed, position_ids=positions, layer_type=self.rope_layer_type)
            compressed = apply_rotary_pos_emb(compressed.unsqueeze(1), cos, sin).squeeze(1)
        else:
            compressed = chunk_kv.new_zeros((batch, 0, self.head_dim))

        compressed_kv = (
            compressed if cache_layer is None else cache_layer.update_compressor_states("indexer", compressed)
        )

        cos_q, sin_q = self.rotary_emb(hidden_states, position_ids=position_ids, layer_type=self.rope_layer_type)
        q = self.q_b_proj(q_residual).view(batch, seq_len, -1, self.head_dim).transpose(1, 2)
        q = apply_rotary_pos_emb(q, cos_q, sin_q).transpose(1, 2)

        index_scores = self.scorer(q, compressed_kv, hidden_states)  # [B, S, T]
        compressed_len = compressed_kv.shape[1]
        top_k = min(self.index_topk, compressed_len)

        # not all queries can attend to the compressed entries. If a query's position
        # is small than the relative position of the key (say m=4, query 2 cannot attend
        # to compressed key at position 4, because it compressed info for states at position
        # 12 to 16. Thus we need to make sure that top_k does not land in that range.
        # Picks that still point past `causal_threshold` (early queries with too few ready
        # blocks) are replaced with a `-1` sentinel that the compressor treats as invalid.
        if compressed_len > 0:
            causal_threshold = (position_ids + 1) // self.compress_rate  # [B, S]
            entry_indices = torch.arange(compressed_len, device=index_scores.device)
            future_mask = entry_indices.view(1, 1, -1) >= causal_threshold.unsqueeze(-1)  # [B, S, T]
            index_scores = index_scores.masked_fill(future_mask, float("-inf"))
            top_k_indices = index_scores.topk(top_k, dim=-1).indices  # [B, S, k]
            invalid = top_k_indices >= causal_threshold.unsqueeze(-1)
            return torch.where(invalid, torch.full_like(top_k_indices, -1), top_k_indices)

        return index_scores.topk(top_k, dim=-1).indices


class ShensiVlCSACompressor(nn.Module):
    """Compressed Sparse Attention compressor (paper §2.3.1, eqs. 9–17). Compresses
    every `compress_rate_csa` (m=4) source tokens and runs a Lightning Indexer on
    top of the compressed KV that scores queries with
    `∑_h w_{t,h} · ReLU(q_{t,h} · K^{IComp}_s)` to gather the top `index_topk`
    entries per query before they reach core attention.

    `kv_proj` / `gate_proj` / `position_bias` project to `2 * head_dim`: each
    token contributes two independent compressed series Ca and Cb stored in
    one tensor. Ca = `[..., :head_dim]` (its contribution to the *next*
    window's compressed entry), Cb = `[..., head_dim:]` (its contribution to
    the *current* window's compressed entry). Compressed entry `w` is the
    softmax-gated convex combination of window `w-1`'s Ca slice with window
    `w`'s Cb slice over `2 * compress_rate_csa` slots — width
    `2 * compress_rate_csa`, stride `compress_rate_csa`. For `w = 0` we need
    the previous window's Ca slice from the *previous forward call*; the
    cache holds it in `overlap_kv` and hands it back here. On the very first
    call (or when there is no cache) that slot stays zero-kv / `-inf`-gate,
    which gives it softmax weight 0.
    """

    rope_layer_type = "compress"

    def __init__(self, config: ShensiVlConfig):
        super().__init__()
        self.compress_rate = config.compress_rates["compressed_sparse_attention"]
        self.head_dim = config.head_dim
        self.kv_proj = nn.Linear(config.hidden_size, 2 * self.head_dim, bias=False)
        self.gate_proj = nn.Linear(config.hidden_size, 2 * self.head_dim, bias=False)
        self.position_bias = nn.Parameter(torch.empty(self.compress_rate, 2 * self.head_dim))
        self.kv_norm = ShensiVlRMSNorm(self.head_dim, eps=config.rms_norm_eps)
        self.rotary_emb = ShensiVlRotaryEmbedding(config)
        self.indexer = ShensiVlIndexer(config)

    def forward(
        self,
        hidden_states: torch.Tensor,
        q_residual: torch.Tensor,
        position_ids: torch.Tensor,
        past_key_values: Cache | None,
        layer_idx: int,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        batch, seq_len, _ = hidden_states.shape
        cache_layer: ShensiVlCSACache | None = (
            past_key_values.layers[layer_idx] if past_key_values is not None else None
        )
        kv = self.kv_proj(hidden_states)
        gate = self.gate_proj(hidden_states)

        if cache_layer is None:
            usable = (kv.shape[1] // self.compress_rate) * self.compress_rate
            chunk_kv, chunk_gate, first_window_position = kv[:, :usable], gate[:, :usable], 0
        else:
            chunk_kv, chunk_gate, first_window_position = cache_layer.store_compression_weights("compressor", kv, gate)

        if chunk_kv.shape[1] > 0:
            n_windows = chunk_kv.shape[1] // self.compress_rate
            ratio = self.compress_rate
            chunk_kv = chunk_kv.view(batch, n_windows, ratio, -1)
            chunk_gate = chunk_gate.view(batch, n_windows, ratio, -1) + self.position_bias

            # Lay out the two series in [B, n_win, 2*ratio, head_dim]: Cb
            # (`[..., head_dim:]`) goes in the second half (current window),
            # Ca of the previous window (`[..., :head_dim]`) goes in the
            # first half. Window 0's first half stays zero-kv / -inf-gate
            # (softmax weight 0) on the very first forward call; on later
            # calls the cache fills it with the saved Ca slice.
            new_kv = chunk_kv.new_zeros((batch, n_windows, 2 * ratio, self.head_dim))
            new_gate = chunk_gate.new_full((batch, n_windows, 2 * ratio, self.head_dim), float("-inf"))
            new_kv[:, :, ratio:] = chunk_kv[..., self.head_dim :]
            new_gate[:, :, ratio:] = chunk_gate[..., self.head_dim :]
            if n_windows > 1:
                new_kv[:, 1:, :ratio] = chunk_kv[:, :-1, :, : self.head_dim]
                new_gate[:, 1:, :ratio] = chunk_gate[:, :-1, :, : self.head_dim]
            if cache_layer is not None:
                prior_kv, prior_gate = cache_layer.update_overlap_state(
                    "compressor", chunk_kv, chunk_gate, self.head_dim
                )
                if prior_kv is not None:
                    new_kv[:, 0, :ratio] = prior_kv.to(new_kv.dtype)
                    new_gate[:, 0, :ratio] = prior_gate.to(new_gate.dtype)

            # Softmax in fp32 for stability (logits in bf16/fp16 can collapse pairs that
            # only differ by a small amount, especially with large window widths).
            compressed = self.kv_norm(
                (new_kv * new_gate.softmax(dim=2, dtype=torch.float32).to(new_kv.dtype)).sum(dim=2)
            )
            positions = torch.arange(n_windows, device=compressed.device)
            positions = positions * self.compress_rate + first_window_position
            positions = positions.unsqueeze(0).expand(batch, -1)
            cos, sin = self.rotary_emb(compressed, position_ids=positions, layer_type=self.rope_layer_type)
            compressed = apply_rotary_pos_emb(compressed.unsqueeze(1), cos, sin).squeeze(1)
        else:
            compressed = chunk_kv.new_zeros((batch, 0, self.head_dim))

        if cache_layer is not None:
            compressed = cache_layer.update_compressor_states("compressor", compressed)
        compressed_kv = compressed.unsqueeze(1)

        # Lightning Indexer: gather top-`index_topk` compressed entries per query.
        # in some cases, the output index can return top-k positions that should not be attended to.
        # Ex: for query at index 5, m=4, and `index_topk=1024`, 1024 index are return but only 2 should be
        # attended to. The indexer marks the rest with `-1`; we clamp before the gather and keep the `valid`
        # to drop them from the per-query block mask afterwards.
        top_k_indices = self.indexer(hidden_states, q_residual, position_ids, past_key_values, layer_idx)  # [B, S, k]
        compressed_len = compressed_kv.shape[2]
        valid = top_k_indices >= 0  # [B, S, k]
        # Per-query block bias: query `t` may only see the cache entries that are <= `seq_len // m`
        # and in these, only the ones marked valid by the indexer. Everything else is `-inf`.
        # While the above negated the indexer, here we apply the "causal" masking.
        safe_indices = torch.where(valid, top_k_indices, torch.full_like(top_k_indices, compressed_len))
        block_bias = compressed_kv.new_full((batch, 1, seq_len, compressed_len + 1), float("-inf"))
        block_bias.scatter_(-1, safe_indices.unsqueeze(1), 0.0)
        return compressed_kv, block_bias[..., :compressed_len]


def repeat_kv(hidden_states: torch.Tensor, n_rep: int) -> torch.Tensor:
    """
    This is the equivalent of torch.repeat_interleave(x, dim=1, repeats=n_rep). The hidden states go from (batch,
    num_key_value_heads, seqlen, head_dim) to (batch, num_attention_heads, seqlen, head_dim)
    """
    batch, num_key_value_heads, slen, head_dim = hidden_states.shape
    if n_rep == 1:
        return hidden_states
    hidden_states = hidden_states[:, :, None, :, :].expand(batch, num_key_value_heads, n_rep, slen, head_dim)
    return hidden_states.reshape(batch, num_key_value_heads * n_rep, slen, head_dim)


def eager_attention_forward(
    module: nn.Module,
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    attention_mask: torch.Tensor | None,
    scaling: float,
    dropout: float | int = 0.0,
    **kwargs,
):
    key_states = repeat_kv(key, module.num_key_value_groups)
    value_states = repeat_kv(value, module.num_key_value_groups)
    attn_weights = torch.matmul(query, key_states.transpose(2, 3)) * scaling
    if attention_mask is not None:
        attn_weights = attn_weights + attention_mask

    sinks = module.sinks.reshape(1, -1, 1, 1).expand(query.shape[0], -1, query.shape[-2], -1)
    combined_logits = torch.cat([attn_weights, sinks], dim=-1)

    # This was not in the original implementation and slightly affect results; it prevents overflow in BF16/FP16
    # when training with bsz>1 we clamp max values.

    combined_logits = combined_logits - combined_logits.max(dim=-1, keepdim=True).values
    probs = F.softmax(combined_logits, dim=-1, dtype=combined_logits.dtype)
    scores = probs[..., :-1]  # we drop the sink here
    attn_weights = nn.functional.dropout(scores, p=dropout, training=module.training).to(value_states.dtype)
    attn_output = torch.matmul(attn_weights, value_states)
    attn_output = attn_output.transpose(1, 2).contiguous()
    return attn_output, attn_weights


COMPRESSOR_CLASSES = {
    "sliding_attention": None,
    "compressed_sparse_attention": ShensiVlCSACompressor,
    "heavily_compressed_attention": ShensiVlHCACompressor,
}


class ShensiVlAttention(nn.Module):
    r"""
    Diff with classic attentions:
    * Shared-KV Multi-Query Attention: `num_key_value_heads = 1`; `kv_proj` projects
      directly to that single KV head and the same tensor is read as both key and
      value.
    * Partial RoPE on the first `rope_head_dim` of each head ("Partial Rotary
      Positional Embedding"). RoPE is also applied with position `-i` to the
      attention output's rope slice, so the contribution of each KV entry stays a
      function of the *relative* distance to the query.
    * Per-head learnable attention sink like gpt OSS.
    * Grouped low-rank output projection for perfs.
    * 3 different cache mechanisms, sliding, sliding+CSA, sliding+HCA.
    """

    def __init__(self, config: ShensiVlConfig, layer_idx: int):
        super().__init__()
        self.config = config
        self.layer_idx = layer_idx
        self.layer_type = config.layer_types[layer_idx]
        # Sliding-only layers use the "main" (plain θ=10000) rope; CSA/HCA layers
        # share the same yarn-scaled "compress" rope as their compressor.
        self.rope_layer_type = "main" if self.layer_type == "sliding_attention" else "compress"
        self.num_heads = config.num_attention_heads
        self.num_key_value_groups = config.num_attention_heads  # single KV head, broadcast to all
        self.head_dim = config.head_dim
        self.sliding_window = config.sliding_window
        self.attention_dropout = config.attention_dropout
        self.is_causal = True
        self.scaling = self.head_dim**-0.5

        self.q_a_proj = nn.Linear(config.hidden_size, config.q_lora_rank, bias=False)
        self.q_a_norm = ShensiVlRMSNorm(config.q_lora_rank, eps=config.rms_norm_eps)
        self.q_b_proj = nn.Linear(config.q_lora_rank, self.num_heads * self.head_dim, bias=False)
        self.q_b_norm = ShensiVlUnweightedRMSNorm(eps=config.rms_norm_eps)
        self.kv_proj = nn.Linear(config.hidden_size, self.head_dim, bias=False)
        self.kv_norm = ShensiVlRMSNorm(self.head_dim, eps=config.rms_norm_eps)
        self.o_a_proj = ShensiVlGroupedLinear(
            self.num_heads * self.head_dim // config.o_groups, config.o_groups * config.o_lora_rank, config.o_groups
        )
        self.o_b_proj = nn.Linear(config.o_groups * config.o_lora_rank, config.hidden_size, bias=False)
        self.sinks = nn.Parameter(torch.empty(self.num_heads))
        self.compressor = (
            COMPRESSOR_CLASSES[self.layer_type](config) if self.layer_type != "sliding_attention" else None
        )

    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: dict[str, tuple[torch.Tensor, torch.Tensor]] | tuple[torch.Tensor, torch.Tensor],
        position_ids: torch.Tensor,
        attention_mask: torch.Tensor | None,
        past_key_values: Cache | None = None,
        **kwargs: Unpack[FlashAttentionKwargs],
    ) -> tuple[torch.Tensor, torch.Tensor | None]:
        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)
        # position_embeddings is a {"main", "compress"} dict from the model; pick the
        # one that matches this layer's rope type (sliding → main, CSA/HCA → compress).
        cos, sin = position_embeddings[self.rope_layer_type]

        q_residual = self.q_a_norm(self.q_a_proj(hidden_states))
        q = self.q_b_proj(q_residual).view(*hidden_shape).transpose(1, 2)
        q = self.q_b_norm(q)
        q = apply_rotary_pos_emb(q, cos, sin)

        kv = self.kv_norm(self.kv_proj(hidden_states)).view(*hidden_shape).transpose(1, 2)
        kv = apply_rotary_pos_emb(kv, cos, sin)

        if past_key_values is not None:  # sliding where K==V
            kv = past_key_values.update(kv, kv, self.layer_idx)[0]

        block_bias = None
        if self.compressor is not None:  # Compressed KV (CSA or HCA)
            compressed_kv, block_bias = self.compressor(
                hidden_states, q_residual, position_ids, past_key_values, self.layer_idx
            )
            kv = torch.cat([kv, compressed_kv], dim=2)

        # The compressor path concatenates extra entries onto the KV axis after the
        # standard sliding-window cache update, so a tensor `attention_mask` (built
        # for the pre-concat KV length) needs to be extended to cover them. The
        # compressor returns a `block_bias` carrying per-query causality + indexer
        # validity over those new slots — cat it in instead of zero-padding (which
        # would let every query see every compressed slot).
        if isinstance(attention_mask, torch.Tensor) and kv.shape[2] > attention_mask.shape[-1]:
            if block_bias is not None:
                attention_mask = torch.cat([attention_mask, block_bias.to(attention_mask.dtype)], dim=-1)
            else:
                attention_mask = F.pad(attention_mask, (0, kv.shape[2] - attention_mask.shape[-1]), value=0.0)

        attention_interface: Callable = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, eager_attention_forward
        )
        attn_output, attn_weights = attention_interface(
            self,
            q,
            kv,
            kv,
            attention_mask,
            dropout=0.0 if not self.training else self.attention_dropout,
            scaling=self.scaling,
            sliding_window=self.sliding_window,
            s_aux=self.sinks,
            **kwargs,
        )

        # K=V in V4, so V picked up rope on its trailing rope slice. Apply the conjugate
        # rotation (`-sin`) at the query position to undo it on the rope slice of the
        # output before the grouped output projection mixes heads. The transpose pair is
        # just a layout fix-up: apply_rotary_pos_emb expects `[B, S, H, D]` (its
        # `unsqueeze_dim=1` adds a head-broadcast dim to cos/sin); attention gave us
        # `[B, H, S, D]`.
        attn_output = apply_rotary_pos_emb(attn_output.transpose(1, 2), cos, -sin).transpose(1, 2)

        grouped = attn_output.reshape(*input_shape, self.config.o_groups, -1)
        grouped = self.o_a_proj(grouped).flatten(2)
        output = self.o_b_proj(grouped)
        return output, attn_weights


class ShensiVlMLP(nn.Module):
    def __init__(self, config: ShensiVlConfig):
        super().__init__()
        self.config = config
        self.hidden_size = config.hidden_size
        self.intermediate_size = config.routed_expert_hidden_size
        self.gate_proj = nn.Linear(self.hidden_size, self.intermediate_size, bias=config.mlp_bias)
        self.up_proj = nn.Linear(self.hidden_size, self.intermediate_size, bias=config.mlp_bias)
        self.down_proj = nn.Linear(self.intermediate_size, self.hidden_size, bias=config.mlp_bias)
        self.act_fn = ACT2FN[config.hidden_act]
        self.limit = config.swiglu_limit
        self.is_hash = True
        self.deepemb = nn.Embedding(config.vocab_size, config.hidden_size)

    def forward(self, hidden_states: torch.Tensor, input_ids: torch.Tensor) -> torch.Tensor:
        gate = self.gate_proj(hidden_states).clamp(max=self.limit)
        up = self.up_proj(hidden_states).clamp(min=-self.limit, max=self.limit)
        return self.down_proj(self.act_fn(gate) * up) * self.deepemb(input_ids)


class ShensiVlTopKRouter(nn.Module):
    def __init__(self, config: ShensiVlConfig):
        super().__init__()
        self.top_k = config.num_experts_per_tok
        self.num_experts = config.num_local_experts
        self.hidden_dim = config.hidden_size
        self.weight = nn.Parameter(torch.empty(self.num_experts, self.hidden_dim))
        self.score_fn = ACT2FN[config.scoring_func]
        self.routed_scaling_factor = config.routed_scaling_factor

    def forward(self, hidden_states: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        flat = hidden_states.reshape(-1, self.hidden_dim)
        logits = F.linear(flat, self.weight)
        scores = self.score_fn(logits)
        indices = torch.topk(scores, self.top_k, dim=-1, sorted=False).indices
        weights = scores.gather(1, indices)
        weights = weights / (weights.sum(dim=-1, keepdim=True) + 1e-20)
        return logits, weights * self.routed_scaling_factor, indices


@use_experts_implementation
class ShensiVlExperts(nn.Module):
    """Collection of expert weights stored as 3D tensors."""

    def __init__(self, config: ShensiVlConfig):
        super().__init__()
        self.num_experts = config.num_local_experts
        self.hidden_dim = config.routed_expert_hidden_size
        self.intermediate_dim = config.intermediate_size
        self.gate_up_proj = nn.Parameter(torch.empty(self.num_experts, 2 * self.intermediate_dim, self.hidden_dim))
        self.down_proj = nn.Parameter(torch.empty(self.num_experts, self.hidden_dim, self.intermediate_dim))
        self.act_fn = ACT2FN[config.hidden_act]
        self.limit = config.swiglu_limit

    def forward(
        self, hidden_states: torch.Tensor, top_k_index: torch.Tensor, top_k_weights: torch.Tensor
    ) -> torch.Tensor:
        final = torch.zeros_like(hidden_states)
        with torch.no_grad():
            mask = F.one_hot(top_k_index, num_classes=self.num_experts).permute(2, 1, 0)
            hit = torch.greater(mask.sum(dim=(-1, -2)), 0).nonzero()
        for expert_idx in hit:
            expert_idx = expert_idx[0]
            if expert_idx == self.num_experts:
                continue
            top_k_pos, token_idx = torch.where(mask[expert_idx])
            current = self._apply_gate(F.linear(hidden_states[token_idx], self.gate_up_proj[expert_idx]))
            current = F.linear(current, self.down_proj[expert_idx]) * top_k_weights[token_idx, top_k_pos, None]
            final.index_add_(0, token_idx, current.to(final.dtype))
        return final

    def _apply_gate(self, gate_up: torch.Tensor) -> torch.Tensor:
        # Lives on the class (like gpt-oss's _apply_gate) so the grouped_mm / batched_mm
        # backends swapped in by `@use_experts_implementation` apply the same clamp +
        # SiLU on top of their packed gate_up output instead of bypassing it.
        gate, up = gate_up.chunk(2, dim=-1)
        gate = gate.clamp(max=self.limit)
        up = up.clamp(min=-self.limit, max=self.limit)
        return self.act_fn(gate) * up


class ShensiVlSparseMoeBlock(nn.Module):
    def __init__(self, config: ShensiVlConfig, layer_idx: int):
        super().__init__()
        self.is_hash = False
        self.gate = (
            ShensiVlTopKRouter(config) if config.attn_res_block_layer_types[layer_idx] == "block_write_layer" else None
        )
        self.experts = (
            ShensiVlExperts(config) if config.attn_res_block_layer_types[layer_idx] == "block_write_layer" else None
        )
        self.routed_expert_down_proj = nn.Linear(config.hidden_size, config.routed_expert_hidden_size, bias=False)
        self.routed_expert_norm = ShensiVlRMSNorm(config.routed_expert_hidden_size, config.rms_norm_eps)
        self.routed_expert_up_proj = nn.Linear(config.routed_expert_hidden_size, config.hidden_size, bias=False)

    def forward(self, hidden_states: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor | None, list[int] | None]:
        batch, seq_len, hidden_dim = hidden_states.shape
        flat = hidden_states.view(-1, hidden_dim)
        _, weights, indices = self.gate(hidden_states)
        routed = self.experts(self.routed_expert_down_proj(flat), indices, weights)
        output = self.routed_expert_up_proj(self.routed_expert_norm(routed)).view(batch, seq_len, hidden_dim)

        coupling_matrix = None
        sharing_layers = getattr(self, "sharing_layers", None)
        if self.training and sharing_layers is not None:
            R = self.gate.weight
            norm_R = torch.norm(R, dim=1)
            distances = torch.cdist(R, R, p=2)
            distances = distances.masked_fill(
                torch.eye(R.size(0), dtype=torch.bool, device=distances.device), float("inf")
            )
            min_dist, _ = torch.min(distances, dim=1)
            eps = min_dist / 2 / norm_R

            low = (1 - eps).unsqueeze(1)
            high = (1 + eps).unsqueeze(1)
            noise = torch.rand_like(R)
            R_tilde = (low + noise * (high - low)) * R

            proxy = F.linear(R_tilde, self.routed_expert_down_proj.weight)
            coupling_matrix = torch.norm(torch.einsum("jDd,id->ijD", self.experts.gate_up_proj, proxy), dim=-1)
        return output, coupling_matrix, sharing_layers


class ShensiVlHyperConnection(nn.Module):
    def __init__(self, config: ShensiVlConfig, is_mlp: bool = False):
        super().__init__()
        self.hc_mult = config.hc_mult
        self.active_streams = config.hc_active_streams
        self.fixed_streams = config.hc_fixed_streams
        self.routed_streams = self.active_streams - self.fixed_streams

        self.input_norm = ShensiVlUnweightedRMSNorm(eps=config.rms_norm_eps)
        self.route_norm = nn.LayerNorm(self.hc_mult * config.hidden_size)

        self.pre_fn = nn.Parameter(torch.empty(self.hc_mult, self.hc_mult * config.hidden_size))
        self.pre_base = nn.Parameter(torch.empty(self.hc_mult))
        self.pre_scale = nn.Parameter(torch.empty(1))

        self.route_fn = nn.Parameter(torch.empty(self.hc_mult, self.hc_mult * config.hidden_size))
        self.route_base = nn.Parameter(torch.empty(self.hc_mult))
        self.route_scale = nn.Parameter(torch.empty(1))

        self.is_mlp = is_mlp
        self.kr = (len(config.hc_conv_kernels) + 1) if self.is_mlp else 1
        if self.is_mlp:
            self.temporal_convs = nn.ModuleList(
                [
                    nn.Conv1d(
                        config.hidden_size,
                        config.hidden_size,
                        ks,
                        padding=ks - 1,
                        groups=config.hidden_size,
                        bias=False,
                    )
                    for ks in config.hc_conv_kernels
                ]
            )

        self.post_fn = nn.Parameter(
            torch.empty(self.active_streams * self.kr, self.active_streams * config.hidden_size)
        )
        self.post_base = nn.Parameter(torch.empty(self.active_streams * self.kr))
        self.post_scale = nn.Parameter(torch.empty(1))

    def forward(self, hidden_streams: torch.Tensor) -> torch.Tensor:
        flat = self.input_norm(hidden_streams.flatten(start_dim=2).float())
        pre = torch.sigmoid(F.linear(flat, self.pre_fn.float()) * self.pre_scale.float() + self.pre_base.float())
        collapsed = (pre.unsqueeze(-1) * hidden_streams).sum(dim=2).to(hidden_streams.dtype)
        return collapsed

    def write_back(self, hidden_streams: torch.Tensor, sublayer_output: torch.Tensor) -> torch.Tensor:
        B, S, hc, H = hidden_streams.shape

        flat = self.route_norm(hidden_streams.flatten(start_dim=2).to(self.route_norm.weight.dtype)).float()
        route_scores = torch.sigmoid(
            F.linear(flat, self.route_fn.float()) * self.route_scale.float() + self.route_base.float()
        )
        fixed_mask = torch.arange(hc, device=route_scores.device) < self.fixed_streams
        route_scores = route_scores.masked_fill(fixed_mask.view(1, 1, -1), -float("inf"))
        fixed_idx = torch.arange(self.fixed_streams, device=hidden_streams.device)
        fixed_idx = fixed_idx.view(1, 1, -1).expand(B, S, -1)
        routed_idx = route_scores.topk(self.routed_streams, dim=-1).indices
        active_idx = torch.cat([fixed_idx, routed_idx], dim=-1)
        p = torch.cat(
            [torch.ones_like(fixed_idx, dtype=route_scores.dtype), route_scores.gather(-1, routed_idx)], dim=-1
        )

        if self.is_mlp:
            x = sublayer_output.transpose(1, 2).to(self.temporal_convs[0].weight.dtype)
            conv_outs = [conv(x)[..., :S] for conv in self.temporal_convs]
            ortho = []
            prevs = [x]
            for g in conv_outs:
                v = g
                for prev in prevs:
                    denom = (prev * prev).sum(dim=1, keepdim=True).clamp_min(self.input_norm.eps)
                    v = v - ((prev * v).sum(dim=1, keepdim=True) / denom) * prev
                ortho.append(v)
                prevs.append(v)
            out_aug = torch.cat([x] + ortho, dim=1).transpose(1, 2).reshape(B, S, self.kr, H).float()
        else:
            out_aug = sublayer_output.float().unsqueeze(-2)

        active_streams = hidden_streams.gather(2, active_idx.unsqueeze(-1).expand(-1, -1, -1, H))
        post = 2 * torch.sigmoid(
            F.linear(self.input_norm(active_streams.flatten(start_dim=2).float()), self.post_fn.float()).view(
                B, S, self.active_streams, self.kr
            )
            * self.post_scale.float()
            + self.post_base.float().view(self.active_streams, self.kr)
        )

        delta = torch.einsum("bskr,bsrh->bskh", post, out_aug) * p.unsqueeze(-1)
        updated_active = delta.to(hidden_streams.dtype)
        return hidden_streams.scatter(2, active_idx.unsqueeze(-1).expand(-1, -1, -1, H), updated_active)


class ShensiVlHyperHead(nn.Module):
    """Final HC-stream collapse; used by `ShensiVlModel` before the shared RMSNorm."""

    def __init__(self, config: ShensiVlConfig):
        super().__init__()
        self.hc_mult = config.hc_mult
        self.input_norm = ShensiVlUnweightedRMSNorm(eps=config.rms_norm_eps)
        self.hc_fn = nn.Parameter(torch.empty(self.hc_mult, self.hc_mult * config.hidden_size))
        self.hc_base = nn.Parameter(torch.empty(self.hc_mult))
        self.hc_scale = nn.Parameter(torch.empty(1))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        flat = self.input_norm(x.flatten(2).float())
        mixes = F.linear(flat, self.hc_fn.float())
        pre = torch.sigmoid(mixes * self.hc_scale.float() + self.hc_base.float())
        return (pre.unsqueeze(-1) * x).sum(dim=2).to(x.dtype)


class ShensiVlAttentionResidual(nn.Module):
    def __init__(self, config, has_router: bool = True):
        super().__init__()
        self.norm = ShensiVlUnweightedRMSNorm(1e-5)
        self.gate_proj = nn.Linear(config.hidden_size, 3 * config.hidden_size, bias=True)
        self.q_proj = nn.Parameter(torch.empty(config.hidden_size, config.hidden_size)) if has_router else None
        self.k_proj = nn.Parameter(torch.empty(config.hidden_size, config.hidden_size))

    def forward(
        self,
        hidden_states: torch.Tensor | None,
        residual: torch.Tensor,
        prefix_sum: torch.Tensor,
        output_norm_weight: torch.Tensor | None,
        num_blocks: int,
    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        delta = hidden_states
        blocks = residual
        state = self.norm(prefix_sum.float() + (delta.float() if delta is not None else 0.0))
        decay, erase, write = torch.sigmoid(
            F.linear(
                state,
                self.gate_proj.weight.float(),
                self.gate_proj.bias.float() if self.gate_proj.bias is not None else None,
            ).reshape(*state.shape[:-1], 3, -1)
        ).unbind(-2)
        forgotten = decay * prefix_sum.float()
        khat = F.normalize(F.linear(state, self.k_proj.float()), dim=-1)
        r = (khat * erase * forgotten).sum(dim=-1, keepdim=True)
        updated = forgotten - khat * r + write * (delta.float() if delta is not None else 0.0)
        if num_blocks > 0:
            values = torch.cat(
                [
                    blocks[..., :num_blocks, :].float(),
                    updated.unsqueeze(-2),
                ],
                dim=-2,
            )
            reciprocal_std = torch.rsqrt(values.square().mean(dim=-1) + self.norm.eps)
            query = F.linear(state, self.q_proj.float())
            logits = (values * query.unsqueeze(-2)).sum(dim=-1) * reciprocal_std
            scores = F.softmax(logits, dim=-1)
            routed = scores.unsqueeze(-1).mul(values).sum(dim=-2)
        else:
            routed = torch.zeros_like(updated)
        output = updated + routed
        if output_norm_weight is not None:
            output = (
                output
                * torch.rsqrt(output.square().mean(dim=-1, keepdim=True) + self.norm.eps)
                * output_norm_weight.float()
            )
        return output.to(prefix_sum.dtype), updated.to(prefix_sum.dtype), blocks


class ShensiVlDecoderLayer(GradientCheckpointingLayer):
    r"""DeepSeek-V4 decoder block (paper §2). Differs from a classic residual block in
    two places:

    The residual is a stack of `hc_mult` parallel streams kept in shape
    `[B, S, hc_mult, D]` throughout the block, mixed in and out via two
    :class:`ShensiVlHyperConnection` modules (Manifold-Constrained Hyper-
    Connections / mHC, paper §2.2; Xie et al., 2026). The mHC mappings constrain
    the residual transform to the manifold of doubly-stochastic matrices via the
    Sinkhorn-Knopp projection — making signal propagation non-expansive across
    deep stacks.

    """

    def __init__(self, config: ShensiVlConfig, layer_idx: int):
        super().__init__()
        self.layer_idx = layer_idx
        self.self_attn = ShensiVlAttention(config, layer_idx)
        self.mlp = (
            ShensiVlMLP(config)
            if config.mlp_layer_types[layer_idx] == "hash_moe"
            else ShensiVlSparseMoeBlock(config, layer_idx)
        )
        self.input_layernorm = ShensiVlRMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.post_attention_layernorm = ShensiVlRMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.attn_hc = ShensiVlHyperConnection(config, is_mlp=False)
        self.ffn_hc = ShensiVlHyperConnection(config, is_mlp=True)
        self.is_block_write_layer = config.attn_res_block_layer_types[layer_idx] == "block_write_layer"
        self.prev_valid_blocks = sum(
            1 for r in config.attn_res_block_layer_types[:layer_idx] if r == "block_write_layer"
        )
        self.block_write_idx = self.prev_valid_blocks
        self.self_attention_attn_res = ShensiVlAttentionResidual(config, self.prev_valid_blocks > 0)
        self.mlp_attn_res = ShensiVlAttentionResidual(config, self.prev_valid_blocks + self.is_block_write_layer > 0)

    def forward(
        self,
        hidden_states: torch.Tensor | None,
        residual: torch.Tensor,
        prefix_sum: torch.Tensor,
        input_ids: torch.Tensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        delta = hidden_states - prefix_sum if hidden_states is not None else None

        hidden_states, prefix_sum, residual = self.self_attention_attn_res(
            delta,
            residual,
            prefix_sum,
            output_norm_weight=self.input_layernorm.weight,
            num_blocks=self.prev_valid_blocks,
        )
        if self.is_block_write_layer:
            residual = torch.cat(
                [
                    residual[..., : self.block_write_idx, :],
                    (hidden_states if hidden_states is not None else prefix_sum).to(residual.dtype).unsqueeze(-2),
                    residual[..., self.block_write_idx + 1 :, :],
                ],
                dim=-2,
            )
            prefix_sum = None

        collapsed = self.attn_hc(hidden_states)
        attn_output, _ = self.self_attn(collapsed, **kwargs)
        hidden_states = self.attn_hc.write_back(hidden_states, attn_output)

        if prefix_sum is None:
            prefix_sum = hidden_states
        else:
            prefix_sum = prefix_sum + hidden_states

        hidden_states, prefix_sum, residual = self.mlp_attn_res(
            prefix_sum,
            residual,
            prefix_sum,
            output_norm_weight=self.post_attention_layernorm.weight,
            num_blocks=self.prev_valid_blocks + self.is_block_write_layer,
        )

        collapsed = self.ffn_hc(hidden_states)
        mlp_output = self.mlp(collapsed, input_ids=input_ids) if self.mlp.is_hash else self.mlp(collapsed)[0]
        hidden_states = self.ffn_hc.write_back(hidden_states, mlp_output)

        prefix_sum = prefix_sum + hidden_states
        return hidden_states, prefix_sum, residual


def get_vision_frame_index(grid_thw: torch.Tensor, kwargs: dict | None = None) -> torch.Tensor:
    """Per-patch index into a temporal embedding table whose row `0` is a zero pad, or pop
    `"frame_index"` from `kwargs`.

    Single-frame clips (`t == 1`, images) map every patch to `0` (no temporal term); frame `f` of a
    multi-frame clip maps to `f + 1`. Precomputable, so the encoder avoids a per-clip `if t > 1` loop.
    """
    if kwargs is not None and (frame_index := kwargs.pop("frame_index", None)) is not None:
        return frame_index
    device = grid_thw.device
    parts = []
    for t, h, w in grid_thw.tolist():
        t, h, w = int(t), int(h), int(w)
        # t == 1 → [0] (padded row 0 = zero); t > 1 → [1..t] → time_emb[0..t-1]
        frames = torch.arange(t, device=device) + int(t > 1)
        parts.append(frames.repeat_interleave(h * w))
    return torch.cat(parts)


class ShensiVlVisionPositionEmbeddings(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.dim = config.hidden_size
        self.num_frames = config.pos_emb_time

        self.position_embeddings = nn.Parameter(
            torch.zeros(config.pos_emb_height, config.pos_emb_width, config.hidden_size)
        )
        # How the (square) learned position grid is resampled to each image's grid.
        self.num_grid_per_side = config.pos_emb_height
        self.interpolation_align_corners = False
        self.interpolation_mode = "bilinear"

        # Time-axis pos_emb are an additive sinusoidal table, i.e. add pos to hiddens rather than rotating
        time_position_embeddings = self.compute_pos_embed()
        self.time_position_embeddings = nn.Buffer(time_position_embeddings, persistent=False)

    def compute_pos_embed(self):
        position_ids = torch.arange(self.num_frames, dtype=torch.float32)
        inv_freq = 1.0 / (10000 ** (torch.arange(0, self.dim, 2, dtype=torch.int64).to(dtype=torch.float) / self.dim))
        freqs = torch.outer(position_ids, inv_freq)  # (M, D/2)
        pos_embed = torch.cat([freqs.sin(), freqs.cos()], dim=1)  # (M, D)
        # Prepend a zero row so frame index 0 (single-frame clips) adds no temporal offset.
        return torch.cat([pos_embed.new_zeros(1, self.dim), pos_embed])  # (M+1, D)

    def forward(self, hidden_states: torch.Tensor, grid_thw: torch.Tensor, **kwargs) -> torch.Tensor:
        # Spatial: bicubically resample the learned grid to each image's (h, w) as a fused weighted
        # gather (`embedding_bag`), equivalent to a per-image `F.interpolate(mode="bicubic")` but a
        # single traceable op over all patches — and faster.
        table = self.position_embeddings.flatten(0, 1)
        interp_indices, interp_weights = get_vision_interpolation_indices_and_weights(
            grid_thw,
            self.num_grid_per_side,
            mode=self.interpolation_mode,
            align_corners=self.interpolation_align_corners,
            kwargs=kwargs,
        )
        pos = F.embedding_bag(interp_indices, table, per_sample_weights=interp_weights.to(table.dtype), mode="sum")
        # Temporal: add a per-frame sinusoid. Row 0 of the table is a zero pad, so single-frame clips
        # (frame index 0) get none.
        pos = pos + self.time_position_embeddings[get_vision_frame_index(grid_thw, kwargs=kwargs)]
        return hidden_states + pos.to(hidden_states.dtype)


class ShensiVlVisionPatchEmbed(nn.Module):
    def __init__(self, config):
        super().__init__()
        patch_size = (
            config.patch_size if not isinstance(config.patch_size, int) else (config.patch_size, config.patch_size)
        )
        self.proj = nn.Conv2d(3, config.hidden_size, kernel_size=patch_size, stride=patch_size, bias=False)
        self.pos_emb = ShensiVlVisionPositionEmbeddings(config)

    def forward(self, pixel_values: torch.Tensor, grid_thw: torch.Tensor, **kwargs) -> torch.Tensor:
        hidden_states = self.proj(pixel_values).view(pixel_values.size(0), -1)
        hidden_states = self.pos_emb(hidden_states, grid_thw, **kwargs)
        return hidden_states


class ShensiVlVisionRotaryEmbedding(nn.Module):
    @deprecate_kwarg("device", version="5.18")
    def __init__(self, config: ShensiVlVisionConfig, device=None):
        super().__init__()
        self.max_seq_len_cached = config.max_position_embeddings
        self.original_max_seq_len = config.max_position_embeddings

        self.config = config

        self.rope_type = self.config.rope_parameters["rope_type"]
        rope_init_fn: Callable = self.compute_default_rope_parameters
        if self.rope_type != "default":
            rope_init_fn = ROPE_INIT_FUNCTIONS[self.rope_type]
        inv_freq, self.attention_scaling = rope_init_fn(self.config, device)

        self.inv_freq = nn.Buffer(inv_freq, persistent=False)
        self.original_inv_freq = nn.Buffer(inv_freq.clone(), persistent=False)

    @staticmethod
    @deprecate_kwarg("device", version="5.18")
    def compute_default_rope_parameters(
        config: ShensiVlVisionConfig, device=None, **kwargs
    ) -> tuple[torch.Tensor, float]:
        """
        Computes the inverse frequencies according to the original RoPE implementation
        Args:
            config ([`~transformers.PreTrainedConfig`]):
                The model configuration.
        Returns:
            Tuple of (`torch.Tensor`, `float`), containing the inverse frequencies for the RoPE embeddings and the
            post-processing scaling factor applied to the computed cos/sin (unused in this type of RoPE).
        """
        base = config.rope_parameters["rope_theta"]
        dim = getattr(config, "head_dim", None) or config.qkv_hidden_size // config.num_attention_heads

        # The reference implementation computes RoPE frequencies INDEPENDENTLY
        # for each spatial dimension using the partitioned head_dim (head_dim // ndim),
        # so both x and y dimensions get identical frequency ranges.
        # This is different from splitting the global inv_freq between dimensions.
        spatial_dim = dim // 2

        attention_factor = 1.0  # Unused in this type of RoPE
        inv_freq = 1.0 / (base ** (torch.arange(0, spatial_dim, 2, dtype=torch.float) / spatial_dim))
        return inv_freq.to(device), attention_factor

    @torch.no_grad()
    @dynamic_rope_update  # power user: used with advanced RoPE types (e.g. dynamic rope)
    def forward(self, x, position_ids):
        position_ids_expanded = position_ids.transpose(0, 1)[..., None].float()  # (positions, 2, 1)
        inv_freq_expanded = (
            self.inv_freq[None, None, :].float().expand(position_ids_expanded.shape[0], 2, -1).to(x.device)
        )  # (positions, 2, freq_dim)

        device_type = x.device.type if isinstance(x.device.type, str) and x.device.type != "mps" else "cpu"
        with maybe_autocast(device_type=device_type, enabled=False):  # Force float32
            freqs = (inv_freq_expanded.float() * position_ids_expanded.float()).transpose(1, 2).flatten(1)
            emb = torch.cat([freqs, freqs], dim=-1)
            cos = emb.cos() * self.attention_scaling
            sin = emb.sin() * self.attention_scaling

        return cos, sin


def apply_rotary_pos_emb_vision(
    q: torch.Tensor, k: torch.Tensor, cos: torch.Tensor, sin: torch.Tensor
) -> tuple[torch.Tensor, torch.Tensor]:
    orig_q_dtype = q.dtype
    orig_k_dtype = k.dtype
    q, k = q.float(), k.float()
    cos, sin = cos.unsqueeze(-2).float(), sin.unsqueeze(-2).float()
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    q_embed = q_embed.to(orig_q_dtype)
    k_embed = k_embed.to(orig_k_dtype)
    return q_embed, k_embed


def vision_attention_forward(
    module: nn.Module,
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    attention_mask: torch.Tensor | None,
    scaling: float,
    dropout: float = 0.0,
    **kwargs,
):
    key_states = repeat_kv(key, module.num_key_value_groups)
    value_states = repeat_kv(value, module.num_key_value_groups)

    attn_weights = torch.matmul(query, key_states.transpose(2, 3)) * scaling
    if attention_mask is not None:
        attn_weights = attn_weights + attention_mask

    attn_weights = F.softmax(attn_weights, dim=-1, dtype=torch.float32).to(query.dtype)
    attn_weights = F.dropout(attn_weights, p=dropout, training=module.training)
    attn_output = torch.matmul(attn_weights, value_states)
    attn_output = attn_output.transpose(1, 2).contiguous()

    return attn_output, attn_weights


class ShensiVlVisionAttention(nn.Module):
    def __init__(self, config: ShensiVlVisionConfig) -> None:
        super().__init__()
        self.dim = config.hidden_size
        self.num_heads = config.num_attention_heads
        self.head_dim = config.qkv_hidden_size // self.num_heads
        self.num_key_value_groups = 1  # needed for eager attention
        self.scaling = self.head_dim**-0.5
        self.config = config
        self.attention_dropout = 0.0
        self.is_causal = False
        self.wqkv = nn.Linear(self.dim, config.qkv_hidden_size * 3, bias=False)
        self.wo = nn.Linear(config.qkv_hidden_size, self.dim, bias=False)

    def forward(
        self,
        hidden_states: torch.Tensor,
        cu_seqlens: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor] | None = None,
        max_seqlen: int | None = None,
        **kwargs,
    ) -> torch.Tensor:
        seq_length = hidden_states.shape[0]

        query_states, key_states, value_states = self.wqkv(hidden_states).chunk(3, dim=-1)

        query_states = query_states.reshape(1, seq_length, -1, self.head_dim)
        key_states = key_states.reshape(1, seq_length, -1, self.head_dim)
        value_states = value_states.reshape(1, seq_length, -1, self.head_dim)

        cos, sin = position_embeddings
        query_states, key_states = apply_rotary_pos_emb_vision(query_states, key_states, cos, sin)

        query_states = query_states.transpose(2, 1)
        key_states = key_states.transpose(2, 1)
        value_states = value_states.transpose(2, 1)

        attention_interface: Callable = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, vision_attention_forward
        )

        if is_flash_attention_requested(self.config):
            # Flash Attention: Use cu_seqlens for variable length attention
            max_seqlen = get_max_seqlen(cu_seqlens, self.config, kwargs={"max_seqlen": max_seqlen})
            attn_output, _ = attention_interface(
                self,
                query_states,
                key_states,
                value_states,
                attention_mask=None,
                scaling=self.scaling,
                dropout=0.0 if not self.training else self.attention_dropout,
                cu_seq_lens_q=cu_seqlens,
                cu_seq_lens_k=cu_seqlens,
                max_length_q=max_seqlen,
                max_length_k=max_seqlen,
                is_causal=False,
                **kwargs,
            )
        else:
            # Other implementations: Process each chunk separately
            lengths = cu_seqlens[1:] - cu_seqlens[:-1]
            splits = [
                torch.split(tensor, lengths.tolist(), dim=2) for tensor in (query_states, key_states, value_states)
            ]

            attn_outputs = [
                attention_interface(
                    self,
                    q,
                    k,
                    v,
                    attention_mask=None,
                    scaling=self.scaling,
                    dropout=0.0 if not self.training else self.attention_dropout,
                    is_causal=False,
                    **kwargs,
                )[0]
                for q, k, v in zip(*splits)
            ]
            attn_output = torch.cat(attn_outputs, dim=1)

        attn_output = attn_output.reshape(seq_length, -1).contiguous()
        return self.wo(attn_output)


class ShensiVlVisionMLP(nn.Module):
    def __init__(self, dim: int, hidden_dim: int, hidden_act: str) -> None:
        super().__init__()
        self.fc1 = nn.Linear(dim, hidden_dim, bias=False)
        self.act = ACT2FN[hidden_act]
        self.fc2 = nn.Linear(hidden_dim, dim, bias=False)

    def forward(self, x) -> torch.Tensor:
        return self.fc2(self.act(self.fc1(x)))


class ShensiVlVisionEncoderLayer(GradientCheckpointingLayer):
    def __init__(self, config: ShensiVlVisionConfig, layer_idx: int) -> None:
        super().__init__()
        self.norm1 = ShensiVlRMSNorm(config.hidden_size, eps=1e-5)
        self.norm2 = ShensiVlRMSNorm(config.hidden_size, eps=1e-5)
        self.attn = ShensiVlVisionAttention(config=config)
        self.mlp = ShensiVlVisionMLP(config.hidden_size, config.intermediate_size, config.hidden_act)
        self.is_block_write_layer = config.attn_res_block_layer_types[layer_idx] == "block_write_layer"
        self.prev_valid_blocks = sum(
            1 for layer_type in config.attn_res_block_layer_types[:layer_idx] if layer_type == "block_write_layer"
        )
        self.block_write_idx = self.prev_valid_blocks
        self.self_attention_attn_res = ShensiVlAttentionResidual(config, self.prev_valid_blocks > 0)
        self.mlp_attn_res = ShensiVlAttentionResidual(config, self.prev_valid_blocks + self.is_block_write_layer > 0)

    def forward(
        self,
        hidden_states: torch.Tensor,
        residual: torch.Tensor | None,
        prefix_sum: torch.Tensor | None,
        cu_seqlens: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor] | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor | None]:
        entry = hidden_states if hidden_states is not None else prefix_sum
        delta = hidden_states - prefix_sum if hidden_states is not None else None

        hidden_states, prefix_sum, residual = self.self_attention_attn_res(
            delta, residual, prefix_sum, output_norm_weight=self.norm1.weight, num_blocks=self.prev_valid_blocks
        )
        if self.is_block_write_layer:
            residual = torch.cat(
                [
                    residual[..., : self.block_write_idx, :],
                    entry.to(residual.dtype).unsqueeze(-2),
                    residual[..., self.block_write_idx + 1 :, :],
                ],
                dim=-2,
            )
            prefix_sum = None

        attn_output = self.attn(
            hidden_states, cu_seqlens=cu_seqlens, position_embeddings=position_embeddings, **kwargs
        )
        hidden_states = hidden_states + attn_output
        prefix_sum = hidden_states if prefix_sum is None else prefix_sum + hidden_states

        hidden_states, prefix_sum, residual = self.mlp_attn_res(
            prefix_sum,
            residual,
            prefix_sum,
            output_norm_weight=self.norm2.weight,
            num_blocks=self.prev_valid_blocks + self.is_block_write_layer,
        )

        mlp_output = self.mlp(hidden_states)
        hidden_states = hidden_states + mlp_output
        prefix_sum = prefix_sum + hidden_states

        return hidden_states, prefix_sum, residual


@auto_docstring
class ShensiVlPreTrainedModel(PreTrainedModel):
    config: ShensiVlConfig
    base_model_prefix = "model"
    supports_gradient_checkpointing = True
    _no_split_modules = ["ShensiVlDecoderLayer"]
    _skip_keys_device_placement = ["past_key_values"]
    # V4 ships eager-only. The non-eager backends are off for the following reasons:
    #
    #   * FlashAttention 2 / 3 cap the head dim at 256; V4's `head_dim=512`
    #     (V4-Flash and V4-Pro both) is structurally incompatible — `flash_attention_2`
    #     and the `kernels-community/vllm-flash-attn3` kernel both fail with
    #     `RuntimeError: FlashAttention forward only supports head dimension at most
    #     256`. FA4 has the same 256 cap, so it's off too.
    #   * SDPA: torch's SDPA kernel doesn't carry the per-head learnable sink term V4
    #     inherits from gpt-oss-style attention.
    #   * FlexAttention: V4 attention concatenates compressor entries onto the KV
    #     axis *inside* the attention block, after the model-level mask was built,
    #     so the resulting KV length doesn't match the BlockMask's `kv_len`.
    #     BlockMask has no runtime resize, and rebuilding it per-block would require
    #     teaching the compressor's variable output count to a `mask_mod` — not
    #     worth it for a path the compressor already owns its own causality
    #     bookkeeping for.
    _supports_flash_attn = False
    _supports_sdpa = False
    _supports_flex_attn = False
    # The compressor's rolling-window buffer / compressed-entries / overlap state
    # lives on the per-layer cache (:class:`ShensiVlHCACache` /
    # :class:`ShensiVlCSACache`) and isn't compatible with :class:`StaticCache`
    # — that path would hand the compressor a :class:`StaticSlidingWindowLayer`
    # with no `store_compression_weights` method. Disabling fullgraph compile
    # keeps generation tests on the dynamic cache build that does dispatch to
    # V4's own cache layers.
    _can_compile_fullgraph = False
    _supports_attention_backend = True
    _can_record_outputs = {
        "router_logits": OutputRecorder(ShensiVlTopKRouter, index=0),
        "attentions": ShensiVlAttention,
        "coupling_matrix": OutputRecorder(ShensiVlSparseMoeBlock, index=1),
        "sharing_layers": OutputRecorder(ShensiVlSparseMoeBlock, index=2),
    }
    config_class = ShensiVlConfig
    _keep_in_fp32_modules_strict = [
        "attn_hc",
        "ffn_hc",
        "hc_head",
        "sinks",
        "position_bias",
        "q_a_norm",
        "kv_norm",
        "input_layernorm",
        "post_attention_layernorm",
        "norm",
    ]
    # DeepSeek-V4-Flash checkpoints mix FP8 and BF16 in the attention compressor /
    # indexer branch: these projections ship in BF16 with no companion `scale_inv`.
    # Listed here (non-strict) so the FP8 quantizer's `get_modules_to_not_convert`
    # auto-skips them; non-strict has no dtype effect at BF16, so they stay BF16.
    _keep_in_fp32_modules = [
        "self_attn.compressor.kv_proj",
        "self_attn.compressor.gate_proj",
        "self_attn.compressor.indexer.kv_proj",
        "self_attn.compressor.indexer.gate_proj",
        "self_attn.compressor.indexer.scorer.weights_proj",
    ]
    _keys_to_ignore_on_load_unexpected = [r"(^|\.)mtp\..*"]
    # ``_is_stateful`` opts out of generation modes that need to roll the cache
    # back across drafts (assisted generation, prompt lookup, contrastive search).
    # The compressor's running-window state isn't rewindable, so `generate`
    # raises a clear error early instead of failing deep in the compressor with
    # a missing-method `AttributeError`.
    _is_stateful = True

    @torch.no_grad()
    def _init_weights(self, module):
        super()._init_weights(module)
        config = getattr(self.config, "text_config", None) or self.config
        std = getattr(config, "initializer_range", 0.02)
        if isinstance(module, ShensiVlTopKRouter):
            init.normal_(module.weight, mean=0.0, std=std)
        elif isinstance(module, ShensiVlExperts):
            init.normal_(module.gate_up_proj, mean=0.0, std=std)
            init.normal_(module.down_proj, mean=0.0, std=std)
        elif isinstance(module, ShensiVlAttention):
            init.zeros_(module.sinks)
        elif isinstance(module, ShensiVlHyperConnection):
            init.normal_(module.pre_fn, mean=0.0, std=std)
            init.zeros_(module.pre_base)
            init.constant_(module.pre_scale, 0.01)
            init.normal_(module.route_fn, mean=0.0, std=std)
            init.zeros_(module.route_base)
            init.ones_(module.route_scale)
            init.normal_(module.post_fn, mean=0.0, std=std)
            init.zeros_(module.post_base)
            init.constant_(module.post_scale, 0.01)
        elif isinstance(module, ShensiVlHyperHead):
            init.normal_(module.hc_fn, mean=0.0, std=std)
            init.zeros_(module.hc_base)
            init.ones_(module.hc_scale)
        elif isinstance(module, (ShensiVlHCACompressor, ShensiVlCSACompressor, ShensiVlIndexer)):
            init.zeros_(module.position_bias)
        elif isinstance(module, ShensiVlRotaryEmbedding):
            for layer_type in module.layer_types:
                rope_init_fn = module.compute_default_rope_parameters
                if module.rope_type[layer_type] != "default":
                    rope_init_fn = ROPE_INIT_FUNCTIONS[module.rope_type[layer_type]]
                curr_inv_freq, _ = rope_init_fn(module.config, layer_type=layer_type)
                init.copy_(getattr(module, f"{layer_type}_inv_freq"), curr_inv_freq)
                init.copy_(getattr(module, f"{layer_type}_original_inv_freq"), curr_inv_freq)
        elif isinstance(module, ShensiVlAttentionResidual):
            gate_width = module.gate_proj.out_features // 3
            nn.init.zeros_(module.gate_proj.weight)
            with torch.no_grad():
                # decay gate open, erase/write gates closed: preserve the prefix by default.
                module.gate_proj.bias[:gate_width] = 2.0
                module.gate_proj.bias[gate_width : 2 * gate_width] = -2.0
                module.gate_proj.bias[2 * gate_width :] = -2.0
            if module.q_proj is not None:
                nn.init.zeros_(module.q_proj)
            nn.init.normal_(module.k_proj, mean=0.0, std=std)
        elif isinstance(module, ShensiVlVisionPositionEmbeddings):
            buffer_value = module.compute_pos_embed()
            init.copy_(module.time_position_embeddings, buffer_value)
            init.trunc_normal_(module.position_embeddings, mean=0.0)

    def post_init(self):
        if hasattr(self, "blocks") and self.blocks:
            self._share_block_routers_and_experts()
            seen_params: dict[int, str] = {}
            registry = getattr(self, "_tied_weights_keys", {}) or {}
            if not isinstance(registry, dict):
                registry = {key: key for key in registry}
            tied_keys = dict(registry)
            for name, param in self.named_parameters(remove_duplicate=False):
                if canonical := seen_params.get(id(param)):
                    tied_keys[name] = canonical
                else:
                    seen_params[id(param)] = name
            self._tied_weights_keys = tied_keys
            self.all_tied_weights_keys = tied_keys
        super().post_init()

    def _share_block_routers_and_experts(self):
        for block in self.blocks:
            pool_mlp = None
            moe_positions = []
            for pos, layer in enumerate(block.language_layers):
                if layer.mlp.is_hash:
                    continue
                if pool_mlp is None:
                    pool_mlp = layer.mlp
                else:
                    layer.mlp.gate = pool_mlp.gate
                    layer.mlp.experts = pool_mlp.experts
                moe_positions.append(pos)
            if pool_mlp is not None:
                pool_mlp.sharing_layers = moe_positions


def get_vision_temporal_merge_index(
    grid_thw: torch.Tensor, kernel_height: int, kernel_width: int, kwargs: dict | None = None
) -> torch.Tensor:
    """Gather index regrouping a flat patch sequence into `(total_merged, t, kernel_height *
    kernel_width)` for the temporal-pooling merger, or pop `"temporal_merge_index"` from `kwargs`.

    Row `m` collects the `t` frames × `kernel_height*kernel_width` source patches that pool into
    merged token `m`; the caller means over the frame axis. Precomputable, so the encoder avoids a
    per-clip `grid_thw.tolist()` loop.
    """
    if kwargs is not None and (index := kwargs.pop("temporal_merge_index", None)) is not None:
        return index
    device = grid_thw.device
    running, rows = 0, []
    for t, h, w in grid_thw.tolist():
        t, h, w = int(t), int(h), int(w)
        new_h, new_w = h // kernel_height, w // kernel_width
        base = torch.arange(running, running + t * h * w, device=device).view(
            t, new_h, kernel_height, new_w, kernel_width
        )
        # (t, new_h, new_w, kh, kw) → (new_h*new_w, t, kh*kw): frame axis kept for the caller's mean.
        base = base.permute(1, 3, 0, 2, 4).reshape(new_h * new_w, t, kernel_height * kernel_width)
        rows.append(base)
        running += t * h * w
    return torch.cat(rows, dim=0)


@auto_docstring
class ShensiVlVisionModel(ShensiVlPreTrainedModel):
    config: ShensiVlVisionConfig
    input_modalities = ("image", "video")
    _can_record_outputs = {"hidden_states": ShensiVlVisionEncoderLayer}

    def __init__(self, config: ShensiVlVisionConfig):
        super().__init__(config)
        self.merge_kernel_size = config.merge_kernel_size
        self.patch_embed = ShensiVlVisionPatchEmbed(config)

        self.rotary_emb = ShensiVlVisionRotaryEmbedding(config)
        self.layers = nn.ModuleList(
            [ShensiVlVisionEncoderLayer(config, layer_idx) for layer_idx in range(config.num_hidden_layers)]
        )
        self.final_layernorm = ShensiVlRMSNorm(config.hidden_size, eps=1e-05)
        self.num_attn_res_blocks = config.attn_res_block_layer_types.count("block_write_layer")
        self.output_attn_res = ShensiVlAttentionResidual(config)
        self.post_init()

    def temporal_patch_merger(
        self,
        hidden_states: torch.Tensor,
        grid_thw: torch.Tensor,
    ) -> torch.Tensor:
        r"""
        Merges temporal frames by spatially pooling patch embeddings across time, returning
        `(total_merged_patches, kernel_height * kernel_width, hidden_dim)`.

        Kept for backward compatibility: `forward` now pools with the export-friendly
        `get_vision_temporal_merge_index` gather instead of this Python per-clip loop.
        """
        hidden_dim = hidden_states.size(-1)
        kernel_height, kernel_width = self.merge_kernel_size

        outputs = []
        running_length = 0
        for t, h, w in grid_thw.tolist():
            seq = hidden_states[running_length : running_length + t * h * w]
            new_height, new_width = h // kernel_height, w // kernel_width
            reshaped_seq = seq.view(t, new_height, kernel_height, new_width, kernel_width, hidden_dim)
            reshaped_seq = reshaped_seq.transpose(2, 3).mean(dim=0)  # temporal pooling
            padded_seq = reshaped_seq.reshape(new_height * new_width, kernel_height * kernel_width, -1)
            outputs.append(padded_seq)
            running_length += t * h * w

        return torch.cat(outputs, dim=0)

    @capture_outputs
    @auto_docstring
    def forward(
        self,
        pixel_values: torch.Tensor,
        grid_thw: torch.Tensor,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.Tensor:
        r"""
        grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        """
        hidden_states = self.patch_embed(pixel_values, grid_thw=grid_thw, **kwargs)
        position_ids = get_vision_position_ids(grid_thw, spatial_merge_size=1, kwargs=kwargs)
        position_ids = position_ids.transpose(0, 1).flip(0)  # (2, positions)
        position_embeddings = self.rotary_emb(hidden_states, position_ids)

        cu_seqlens, max_seqlen = get_vision_attention_seqlens(
            grid_thw, self.config, merge_temporal=True, kwargs=kwargs
        )

        prefix_sum = hidden_states
        block_residual = hidden_states.new_zeros(
            *hidden_states.shape[:-1], self.num_attn_res_blocks, hidden_states.shape[-1]
        )
        hidden_states = None

        for block in self.layers:
            hidden_states, prefix_sum, block_residual = block(
                hidden_states,
                residual=block_residual,
                prefix_sum=prefix_sum,
                cu_seqlens=cu_seqlens,
                max_seqlen=max_seqlen,
                position_embeddings=position_embeddings,
                **kwargs,
            )
        hidden_states, _, _ = self.output_attn_res(
            hidden_states - prefix_sum if hidden_states is not None else None,
            block_residual,
            prefix_sum,
            output_norm_weight=self.final_layernorm.weight,
            num_blocks=self.num_attn_res_blocks,
        )

        merge_index = get_vision_temporal_merge_index(grid_thw, *self.merge_kernel_size, kwargs=kwargs)
        pooled_hidden_states = hidden_states[merge_index].mean(dim=1)

        return BaseModelOutputWithPooling(
            last_hidden_state=hidden_states,
            pooler_output=pooled_hidden_states,
        )


# Adapted from transformers.models.vit.modeling_vit.eager_attention_forward
def cross_attention_forward(
    module: nn.Module,
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    attention_mask: torch.Tensor | None,
    scaling: float,
    dropout: float = 0.0,
    **kwargs,
):
    # Take the dot product between "query" and "key" to get the raw attention scores.
    attn_weights = torch.matmul(query, key.transpose(-1, -2)) * scaling

    # Normalize the attention scores to probabilities.
    attn_weights = nn.functional.softmax(attn_weights, dim=-1, dtype=torch.float32).to(query.dtype)

    # This is actually dropping out entire tokens to attend to, which might
    # seem a bit unusual, but is taken from the original Transformer paper.
    attn_weights = nn.functional.dropout(attn_weights, p=dropout, training=module.training)

    attn_output = torch.matmul(attn_weights, value)
    attn_output = attn_output.transpose(1, 2).contiguous()

    return attn_output, attn_weights


class ShensiVlPoolerCrossAttention(nn.Module):
    """It's different from other cross-attention layers, doesn't have output projection layer (o_proj)"""

    # in case of modular refactoring - o_proj can be replaces with nn.Identity()

    def __init__(self, q_dim, kv_dim, num_heads, _attn_implementation=None):
        super().__init__()
        self.embed_dim = q_dim
        self.num_heads = num_heads
        self.head_dim = self.embed_dim // self.num_heads
        if self.head_dim * self.num_heads != self.embed_dim:
            raise ValueError(
                f"embed_dim must be divisible by num_heads (got `embed_dim`: {self.embed_dim} and `num_heads`:"
                f" {self.num_heads})."
            )
        self.scale = self.head_dim**-0.5
        self.dropout = 0.0
        self.is_causal = False
        self.k_proj = nn.Linear(kv_dim, q_dim)
        self.v_proj = nn.Linear(kv_dim, q_dim)
        self.q_proj = nn.Linear(q_dim, q_dim)
        self._attn_implementation = _attn_implementation

    def forward(
        self,
        queries: torch.Tensor,
        keys: torch.Tensor,
        values: torch.Tensor,
        attention_mask: torch.Tensor | None = None,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """Input shape: Batch x Time x Channel"""

        batch_size, q_seq_length, embed_dim = queries.shape
        kv_seq_length = keys.shape[1]

        queries = self.q_proj(queries)
        keys = self.k_proj(keys)
        values = self.v_proj(values)

        queries = queries.view(batch_size, q_seq_length, self.num_heads, self.head_dim).transpose(1, 2)
        keys = keys.view(batch_size, kv_seq_length, self.num_heads, self.head_dim).transpose(1, 2)
        values = values.view(batch_size, kv_seq_length, self.num_heads, self.head_dim).transpose(1, 2)

        attention_interface: Callable = ALL_ATTENTION_FUNCTIONS.get_interface(
            self._attn_implementation, cross_attention_forward
        )

        attn_output, attn_weights = attention_interface(
            self,
            queries,
            keys,
            values,
            attention_mask,
            is_causal=self.is_causal,
            scaling=self.scale,
            dropout=0.0 if not self.training else self.dropout,
        )

        attn_output = attn_output.reshape(batch_size, q_seq_length, embed_dim).contiguous()

        return attn_output, attn_weights


class ShensiVlCrossBlock(GradientCheckpointingLayer):
    def __init__(
        self,
        config: ShensiVlConfig,
        vision_layers: Sequence[nn.Module],
        language_layers: Sequence[nn.Module],
    ):
        super().__init__()
        vision_config, text_config = config.vision_config, config.text_config

        self.vision_layers = tuple(vision_layers)
        self.language_layers = tuple(language_layers)
        self.vision_to_language_attention = ShensiVlPoolerCrossAttention(
            text_config.hidden_size,
            vision_config.hidden_size,
            config.num_cross_attention_heads,
        )
        self.language_to_vision_attention = ShensiVlPoolerCrossAttention(
            vision_config.hidden_size,
            text_config.hidden_size,
            config.num_cross_attention_heads,
        )
        self.gate = nn.Parameter(torch.zeros(text_config.hc_mult + 1))

    def _run_vision_layers(
        self,
        hidden_states: torch.Tensor | None,
        residual: torch.Tensor | None,
        prefix_sum: torch.Tensor | None,
        cu_seqlens: torch.Tensor | None,
        position_embeddings: tuple | None,
        max_seqlen: int | None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[torch.Tensor | None, torch.Tensor | None, torch.Tensor | None]:
        if hidden_states is not None:
            for layer in self.vision_layers:
                hidden_states, prefix_sum, residual = layer(
                    hidden_states,
                    residual,
                    prefix_sum,
                    cu_seqlens,
                    position_embeddings,
                    max_seqlen=max_seqlen,
                    **kwargs,
                )
        return hidden_states, prefix_sum, residual

    def _cross_modal_exchange(
        self,
        hidden_states: torch.Tensor | None,
        prefix_sum: torch.Tensor,
        vision_prefix_sum: torch.Tensor | None,
        evidence_mask: torch.Tensor | None,
        guidance_mask: torch.Tensor | None,
        vision_patch_to_row: torch.Tensor | None,
    ) -> tuple[torch.Tensor | None, torch.Tensor | None]:
        if vision_prefix_sum is None:
            return hidden_states, vision_prefix_sum

        # The packed vision sequence is shared across the batch; expand it so query and key
        # batch sizes match. Per-row masks make each sample attend only to its own patches.
        batch_size = prefix_sum.shape[0]

        vision_memory = vision_prefix_sum.unsqueeze(0).expand(batch_size, -1, -1)
        language_queries = prefix_sum + (hidden_states if hidden_states is not None else prefix_sum)
        # Collapse the hc streams before any cross-attention: both projectors live in the
        # language hidden-space, so query, key and value must all be 2-D in sequence-time.
        language_queries = language_queries.mean(dim=2)
        retrieved_evidence = self.vision_to_language_attention(
            language_queries,
            vision_memory,
            vision_memory,
            attention_mask=evidence_mask,
        )[0]
        if hidden_states is not None:
            # Split the fused gate along the stream dimension: `hc_mult` evidence gates
            # followed by a single guidance gate.
            evidence_gate, guidance_gate = self.gate.split([self.gate.size(0) - 1, 1])
            hidden_states = hidden_states + torch.tanh(evidence_gate)[None, None, :, None] * (
                retrieved_evidence.unsqueeze(2)
            )

        retrieved_guidance = self.language_to_vision_attention(
            vision_memory,
            language_queries,
            language_queries,
            attention_mask=guidance_mask,
        )[0]
        # Each patch lives in exactly one sample; keep only its own row's guidance update.
        patch_indices = torch.arange(vision_prefix_sum.shape[0], device=vision_prefix_sum.device)
        retrieved_guidance = retrieved_guidance[vision_patch_to_row, patch_indices]
        vision_prefix_sum = vision_prefix_sum + torch.tanh(guidance_gate) * retrieved_guidance

        return hidden_states, vision_prefix_sum

    def forward(
        self,
        hidden_states: torch.Tensor | None,
        residual: torch.Tensor,
        prefix_sum: torch.Tensor,
        input_ids: torch.Tensor | None = None,
        position_embeddings: dict | None = None,
        position_ids: torch.LongTensor | None = None,
        attention_mask: torch.Tensor | None = None,
        past_key_values: Cache | None = None,
        vision_hidden_states: torch.Tensor | None = None,
        vision_residual: torch.Tensor | None = None,
        vision_prefix_sum: torch.Tensor | None = None,
        vision_cu_seqlens: torch.Tensor | None = None,
        vision_position_embeddings: tuple | None = None,
        vision_max_seqlen: int | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[
        torch.Tensor | None,
        torch.Tensor,
        torch.Tensor,
        torch.Tensor | None,
        torch.Tensor | None,
        torch.Tensor | None,
        list[torch.Tensor] | None,
    ]:
        evidence_mask = kwargs.pop("evidence_mask", None)
        guidance_mask = kwargs.pop("guidance_mask", None)
        vision_patch_to_row = kwargs.pop("vision_patch_to_row", None)
        run_vision_layers = kwargs.pop("run_vision_layers", True)

        # Block 0's vision layers may already have run during round-0 preparation (the placeholder
        # fill needs refined features before any language layer); the caller says which.
        if run_vision_layers:
            vision_hidden_states, vision_prefix_sum, vision_residual = self._run_vision_layers(
                hidden_states=vision_hidden_states,
                residual=vision_residual,
                prefix_sum=vision_prefix_sum,
                cu_seqlens=vision_cu_seqlens,
                position_embeddings=vision_position_embeddings,
                max_seqlen=vision_max_seqlen,
                **kwargs,
            )

        layer_hidden_states = [] if kwargs.get("output_hidden_states", False) else None
        for layer in self.language_layers:
            hidden_states, prefix_sum, residual = layer(
                hidden_states,
                residual,
                prefix_sum,
                input_ids,
                position_embeddings=position_embeddings,
                position_ids=position_ids,
                attention_mask=attention_mask,
                past_key_values=past_key_values,
                **kwargs,
            )
            if layer_hidden_states is not None:
                layer_hidden_states.append(hidden_states)

        hidden_states, vision_prefix_sum = self._cross_modal_exchange(
            hidden_states,
            prefix_sum,
            vision_prefix_sum,
            evidence_mask,
            guidance_mask,
            vision_patch_to_row,
        )

        return (
            hidden_states,
            prefix_sum,
            residual,
            vision_hidden_states,
            vision_prefix_sum,
            vision_residual,
            layer_hidden_states,
        )


class ShensiVlReasoning(nn.Module):
    def __init__(self, config: ShensiVlConfig):
        super().__init__()
        text_config = config.text_config

        self.gate = nn.Parameter(torch.ones(text_config.hc_mult))
        self.proj = nn.Linear(text_config.hidden_size, text_config.hidden_size)
        self.update_gate = nn.Linear(text_config.hidden_size * 2, text_config.hidden_size)

    def forward(
        self,
        retrieved_evidence: torch.Tensor,
        reasoning_state: torch.Tensor,
        hidden_states: torch.Tensor | None,
    ) -> tuple[torch.Tensor, torch.Tensor | None]:
        evolving = self.proj(retrieved_evidence)
        update_gate = torch.sigmoid(self.update_gate(torch.cat([evolving, reasoning_state], dim=-1)))
        reasoning_state = update_gate * reasoning_state + (1 - update_gate) * evolving
        if hidden_states is not None:
            hidden_states + torch.tanh(self.gate)[None, None, :, None] * (
                retrieved_evidence + reasoning_state
            ).unsqueeze(2)
        else:
            hidden_states = None
        return reasoning_state, hidden_states


class ShensiVlLoopBlock(GradientCheckpointingLayer):
    def __init__(
        self,
        config: ShensiVlConfig,
        vision_layers: Sequence[nn.Module],
        language_layers: Sequence[nn.Module],
        vision_output_attn_res: nn.Module,
        output_attn_res: nn.Module,
        vision_final_norm: nn.Module,
    ):
        super().__init__()
        vision_config, text_config = config.vision_config, config.text_config

        self.vision_layers = tuple(vision_layers)
        self.language_layers = tuple(language_layers)
        self.vision_to_language_attention = ShensiVlPoolerCrossAttention(
            text_config.hidden_size,
            vision_config.hidden_size,
            config.num_cross_attention_heads,
        )
        object.__setattr__(self, "vision_output_attn_res", vision_output_attn_res)
        object.__setattr__(self, "output_attn_res", output_attn_res)
        object.__setattr__(self, "vision_final_norm", vision_final_norm)
        self.reasoning = ShensiVlReasoning(config)

    def _run_vision_layers(
        self,
        hidden_states: torch.Tensor | None,
        residual: torch.Tensor | None,
        prefix_sum: torch.Tensor | None,
        cu_seqlens: torch.Tensor | None,
        position_embeddings: tuple | None,
        max_seqlen: int | None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[torch.Tensor | None, torch.Tensor | None, torch.Tensor | None]:
        if hidden_states is not None:
            for layer in self.vision_layers:
                hidden_states, prefix_sum, residual = layer(
                    hidden_states,
                    residual,
                    prefix_sum,
                    cu_seqlens,
                    position_embeddings,
                    max_seqlen=max_seqlen,
                    **kwargs,
                )
        return hidden_states, prefix_sum, residual

    def _run_damped_language_layers(
        self,
        hidden_states: torch.Tensor | None,
        residual: torch.Tensor,
        prefix_sum: torch.Tensor,
        damping: float,
        past_key_values: Cache | None,
        input_ids: torch.LongTensor | None,
        position_embeddings: dict,
        position_ids: torch.LongTensor,
        attention_mask: torch.Tensor,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[torch.Tensor | None, torch.Tensor, torch.Tensor, list[torch.Tensor] | None]:
        damped_connections = []
        if damping < 1.0:
            for layer in self.language_layers:
                for connection in (layer.attn_hc, layer.ffn_hc):
                    original_write_back = connection.write_back
                    damped_connections.append((connection, original_write_back))
                    connection.write_back = lambda hidden, output, _original=original_write_back, _damping=damping: (
                        _original(hidden, _damping * output)
                    )
        try:
            layer_mask = attention_mask
            if past_key_values is None and attention_mask is not None:
                layer_mask = attention_mask[..., -prefix_sum.shape[1] :]
            layer_hidden_states = [] if kwargs.get("output_hidden_states", False) else None
            for layer in self.language_layers:
                hidden_states, prefix_sum, residual = layer(
                    hidden_states,
                    residual,
                    prefix_sum,
                    input_ids,
                    position_embeddings=position_embeddings,
                    position_ids=position_ids,
                    attention_mask=layer_mask,
                    past_key_values=past_key_values,
                    **kwargs,
                )
                if layer_hidden_states is not None:
                    layer_hidden_states.append(hidden_states)
        finally:
            for connection, original_write_back in damped_connections:
                connection.write_back = original_write_back
        return hidden_states, prefix_sum, residual, layer_hidden_states

    def forward(
        self,
        hidden_states: torch.Tensor | None,
        residual: torch.Tensor,
        prefix_sum: torch.Tensor,
        input_ids: torch.Tensor | None = None,
        position_embeddings: dict | None = None,
        position_ids: torch.LongTensor | None = None,
        attention_mask: torch.Tensor | None = None,
        past_key_values: Cache | None = None,
        vision_hidden_states: torch.Tensor | None = None,
        vision_residual: torch.Tensor | None = None,
        vision_prefix_sum: torch.Tensor | None = None,
        vision_cu_seqlens: torch.Tensor | None = None,
        vision_position_embeddings: tuple | None = None,
        vision_max_seqlen: int | None = None,
        num_attn_res_blocks: int = 0,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[
        torch.Tensor | None,
        torch.Tensor,
        torch.Tensor,
        torch.Tensor | None,
        torch.Tensor | None,
        torch.Tensor | None,
        list[torch.Tensor] | None,
    ]:
        evidence_mask = kwargs.pop("evidence_mask", None)
        run_vision_layers = kwargs.pop("run_vision_layers", True)

        if run_vision_layers:
            vision_hidden_states, vision_prefix_sum, vision_residual = self._run_vision_layers(
                hidden_states=vision_hidden_states,
                residual=vision_residual,
                prefix_sum=vision_prefix_sum,
                cu_seqlens=vision_cu_seqlens,
                position_embeddings=vision_position_embeddings,
                max_seqlen=vision_max_seqlen,
                **kwargs,
            )

        vision_final = (
            self.vision_output_attn_res(
                vision_hidden_states,
                vision_residual,
                vision_prefix_sum,
                output_norm_weight=self.vision_final_norm.weight,
                num_blocks=num_attn_res_blocks,
            )[0]
            if vision_hidden_states is not None
            else None
        )

        initial_queries = (prefix_sum + (hidden_states if hidden_states is not None else prefix_sum)).mean(dim=2)
        reasoning_state = torch.zeros_like(initial_queries)

        previous = None
        first_delta = None
        hidden_delta = None
        first_reasoning_delta = None
        reasoning_delta = None
        previous_reasoning_state = None
        delta_history = deque(maxlen=8)
        orbit_history = deque(maxlen=8)
        orbit_counts = deque(maxlen=8)
        while True:
            damping = 0.25
            converged = first_delta is not None and hidden_delta <= 1e-3 * first_delta
            thought_settled = first_reasoning_delta is not None and reasoning_delta <= 1e-1 * first_reasoning_delta
            stream_stalled = delta_history and max(delta_history) >= 0.5 * first_delta
            stop = bool(converged or (thought_settled and stream_stalled) or sum(orbit_counts) >= 3)

            language_queries = (prefix_sum + (hidden_states if hidden_states is not None else prefix_sum)).mean(dim=2)
            if vision_final is not None:
                final_evidence = vision_final.unsqueeze(0).expand(prefix_sum.shape[0], -1, -1)
                retrieved_evidence = self.vision_to_language_attention(
                    language_queries,
                    final_evidence,
                    final_evidence,
                    attention_mask=evidence_mask,
                )[0]
            else:
                retrieved_evidence = language_queries

            reasoning_state, hidden_states = self.reasoning(retrieved_evidence, reasoning_state, hidden_states)

            hidden_states, prefix_sum, residual, layer_hidden_states = self._run_damped_language_layers(
                hidden_states,
                residual,
                prefix_sum,
                damping,
                past_key_values if stop else None,
                input_ids,
                position_embeddings,
                position_ids,
                attention_mask,
                **{**kwargs, "output_attentions": kwargs.get("output_attentions", False) and stop},
            )
            if previous is not None:
                hidden_delta = (hidden_states - previous).abs().max()
                if first_delta is None:
                    first_delta = hidden_delta
                delta_history.append(hidden_delta)
            previous = hidden_states
            if previous_reasoning_state is not None:
                reasoning_delta = (reasoning_state - previous_reasoning_state).abs().max()
                if first_reasoning_delta is None:
                    first_reasoning_delta = reasoning_delta
            previous_reasoning_state = reasoning_state
            if orbit_history:
                orbit_return = min((hidden_states.detach() - past).abs().max() for past in orbit_history)
                orbit_history.append(hidden_states.detach())
                orbit_counts.append(1 if orbit_return <= 1e-1 * first_delta else 0)
            else:
                orbit_history.append(hidden_states.detach())
            if stop:
                break

        hidden_states, _, _ = self.output_attn_res(
            hidden_states,
            residual,
            prefix_sum,
            output_norm_weight=None,
            num_blocks=num_attn_res_blocks,
        )

        return (
            hidden_states,
            prefix_sum,
            residual,
            vision_hidden_states,
            vision_prefix_sum,
            vision_residual,
            layer_hidden_states,
        )


class ShensiVlMultimodalProjection(nn.Module):
    def __init__(self, config: ShensiVlConfig):
        super().__init__()
        self.hidden_size = config.vision_config.hidden_size * (
            config.vision_config.merge_kernel_size[0] * config.vision_config.merge_kernel_size[1]
        )
        self.fc1 = nn.Linear(self.hidden_size, self.hidden_size, bias=False)
        self.act = nn.GELU()
        self.fc2 = nn.Linear(self.hidden_size, config.text_config.hidden_size, bias=False)
        self.post_norm = nn.RMSNorm(config.text_config.hidden_size, config.projection_layer_norm_eps)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        batch_size = hidden_states.shape[0]
        hidden_states = hidden_states.view(batch_size, -1, self.hidden_size)
        hidden_states = self.fc2(self.act(self.fc1(hidden_states)))
        return self.post_norm(hidden_states)


@auto_docstring(
    custom_intro="""
    Base class for ShensiVl outputs, with hidden states and attentions.
    """
)
@dataclass
class ShensiVlModelOutputWithPast(BaseModelOutputWithPast):
    r"""
    past_key_values (`Cache`, *optional*, returned when `use_cache=True` is passed or when `config.use_cache=True`):
        It is a [`~cache_utils.Cache`] instance. For more details, see our [kv cache guide](https://huggingface.co/docs/transformers/en/kv_cache).

        Contains pre-computed hidden-states (key and values in the self-attention blocks) that can be used (see
        `past_key_values` input) to speed up sequential decoding.
    image_hidden_states (`torch.FloatTensor`, *optional*):
        A `torch.FloatTensor` of size `(batch_size, num_images, sequence_length, hidden_size)`.
        image_hidden_states of the model produced by the vision encoder and after projecting the last hidden state.
    """

    image_hidden_states: torch.FloatTensor | None = None


def find_spans(input_ids: torch.Tensor, token_id: int) -> list[list[tuple[int, int]]]:
    r"""
    Finds contiguous runs of `token_id` in each row of `input_ids`.

    Args:
        input_ids (`torch.Tensor` of shape `(batch_size, sequence_length)`):
            Input token ids.
        token_id (`int`):
            The media placeholder token to locate.

    Returns:
        `list[list[tuple[int, int]]]`: Per input row, a list of `(start, length)` spans.
    """
    spans = []
    for row in input_ids.tolist():
        row_spans, index = [], 0
        while index < len(row):
            if row[index] == token_id:
                end = index
                while end < len(row) and row[end] == token_id:
                    end += 1
                row_spans.append((index, end - index))
                index = end
            else:
                index += 1
        spans.append(row_spans)
    return spans


def get_clip_counts(
    grid_thw: torch.Tensor,
    kernel_height: int,
    kernel_width: int,
) -> tuple[list[int], list[int]]:
    r"""
    Computes per-clip patch counts from `grid_thw`, before and after temporal patch merging.

    Args:
        grid_thw (`torch.Tensor` of shape `(num_clips, 3)`):
            Per clip, the `(temporal, height, width)` patch grid.
        kernel_height (`int`):
            Spatial merge kernel height.
        kernel_width (`int`):
            Spatial merge kernel width.

    Returns:
        `tuple[list[int], list[int]]`: `(merged_counts, patch_counts)` — patches after
        merging (`h // kernel_height * w // kernel_width`) and before merging (`t * h * w`).
    """
    merged_counts = [(height // kernel_height) * (width // kernel_width) for _, height, width in grid_thw.tolist()]
    patch_counts = [temporal * height * width for temporal, height, width in grid_thw.tolist()]
    return merged_counts, patch_counts


def split_blocks(layers: nn.ModuleList, layer_types: list[str]) -> list[list[nn.Module]]:
    # Each tower chunks its layers by its own block-write layer positions; the stacks
    # only need to agree on the number of blocks, not on their internal sizes.
    write_indices = [i for i, t in enumerate(layer_types) if t == "block_write_layer"]
    return [list(layers[start:end]) for start, end in zip(write_indices, write_indices[1:] + [len(layers)])]


@auto_docstring
class ShensiVlModel(ShensiVlPreTrainedModel):
    def __init__(self, config: ShensiVlConfig):
        super().__init__(config)
        self.vision_tower = ShensiVlVisionModel._from_config(config.vision_config)
        self.language_model = AutoModel.from_config(config.text_config)
        self.mm_projector = ShensiVlMultimodalProjection(config)
        vision_config, text_config = config.vision_config, config.text_config
        num_vision_attn_res_blocks = vision_config.attn_res_block_layer_types.count("block_write_layer")
        num_text_attn_res_blocks = text_config.attn_res_block_layer_types.count("block_write_layer")
        assert num_vision_attn_res_blocks == num_text_attn_res_blocks, (
            "DeepRecur requires the vision and language stacks to have the same number of attention-residual blocks."
        )

        self.num_attn_res_blocks = num_vision_attn_res_blocks

        vision_chunks = split_blocks(self.vision_tower.layers, vision_config.attn_res_block_layer_types)
        language_chunks = split_blocks(self.language_model.layers, text_config.attn_res_block_layer_types)
        self.blocks = nn.ModuleList(
            [
                ShensiVlCrossBlock(config, vision_chunks[i], language_chunks[i])
                for i in range(self.num_attn_res_blocks - 1)
            ]
            + [
                ShensiVlLoopBlock(
                    config,
                    vision_chunks[-1],
                    language_chunks[-1],
                    self.vision_tower.output_attn_res,
                    self.language_model.output_attn_res,
                    self.vision_tower.final_layernorm,
                )
            ]
        )
        self.post_init()

    def get_input_embeddings(self):
        return self.language_model.get_input_embeddings()

    def set_input_embeddings(self, value):
        self.language_model.set_input_embeddings(value)

    def get_placeholder_mask(
        self,
        input_ids: torch.LongTensor,
        inputs_embeds: torch.FloatTensor,
        image_features: torch.FloatTensor | None = None,
        video_features: torch.FloatTensor | None = None,
    ):
        """
        Obtains multimodal placeholder mask from `input_ids` or `inputs_embeds`, and checks that the placeholder token count is
        equal to the length of multimodal features. If the lengths are different, an error is raised.
        """
        if input_ids is None:
            special_image_mask = inputs_embeds == self.get_input_embeddings()(
                torch.full((), self.config.image_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            special_image_mask = special_image_mask.all(-1)
            special_video_mask = inputs_embeds == self.get_input_embeddings()(
                torch.full((), self.config.video_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            special_video_mask = special_video_mask.all(-1)
        else:
            special_image_mask = input_ids == self.config.image_token_id
            special_video_mask = input_ids == self.config.video_token_id

        n_image_tokens = special_image_mask.sum()
        special_image_mask = special_image_mask.unsqueeze(-1).to(inputs_embeds.device)
        if image_features is not None:
            torch_compilable_check(
                n_image_tokens * inputs_embeds.shape[-1] == image_features.numel(),
                f"Image features and image tokens do not match, tokens: {n_image_tokens}, features: {image_features.shape[0]}",
            )

        n_video_tokens = special_video_mask.sum()
        special_video_mask = special_video_mask.unsqueeze(-1).to(inputs_embeds.device)
        if video_features is not None:
            torch_compilable_check(
                n_video_tokens * inputs_embeds.shape[-1] == video_features.numel(),
                f"Video features and video tokens do not match, tokens: {n_video_tokens}, features: {video_features.shape[0]}",
            )
        return special_image_mask, special_video_mask

    @capture_outputs
    def forward(
        self,
        input_ids: torch.LongTensor | None = None,
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        past_key_values: Cache | None = None,
        inputs_embeds: torch.FloatTensor | None = None,
        use_cache: bool | None = None,
        pixel_values: torch.Tensor | None = None,
        image_grid_thw: torch.LongTensor | None = None,
        pixel_values_videos: torch.Tensor | None = None,
        video_grid_thw: torch.LongTensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | ShensiVlModelOutputWithPast:
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")
        if use_cache and past_key_values is None:
            past_key_values = DynamicCache(config=self.config.text_config)

        if inputs_embeds is None:
            multimodal_mask = (input_ids == self.config.image_token_id) | (
                input_ids == getattr(self.config, "video_token_id", -1)
            )
            llm_input_ids = input_ids.clone()
            llm_input_ids[multimodal_mask] = 0
            inputs_embeds = self.get_input_embeddings()(llm_input_ids)
        elif input_ids is None and (pixel_values is not None or pixel_values_videos is not None):
            input_ids = torch.full(inputs_embeds.shape[:2], 0, dtype=torch.long, device=inputs_embeds.device)
            image_embed = self.get_input_embeddings()(
                torch.full((), self.config.image_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            input_ids[(inputs_embeds == image_embed).all(dim=-1)] = self.config.image_token_id
            video_token_id = getattr(self.config, "video_token_id", None)
            if video_token_id is not None:
                video_embed = self.get_input_embeddings()(
                    torch.full((), video_token_id, dtype=torch.long, device=inputs_embeds.device)
                )
                input_ids[(inputs_embeds == video_embed).all(dim=-1)] = video_token_id

        if position_ids is None:
            past_seen = past_key_values.get_seq_length() if past_key_values is not None else 0
            position_ids = torch.arange(inputs_embeds.shape[1], device=inputs_embeds.device) + past_seen
            position_ids = position_ids.unsqueeze(0)

        vision_tower = self.vision_tower
        vision_config = self.config.vision_config
        kernel_height, kernel_width = vision_config.merge_kernel_size
        sequence_length = inputs_embeds.shape[1]
        embed_dtype = inputs_embeds.dtype
        device = inputs_embeds.device

        vision_hidden_states = vision_residual = vision_prefix_sum = None
        vision_cu_seqlens = vision_position_embeddings = vision_max_seqlen = None
        vision_evidence_mask = vision_guidance_mask = vision_patch_to_row = None
        all_patch_counts: list[int] = []
        all_spans: list[list[tuple[int, int]]] = []

        if pixel_values is not None and image_grid_thw is not None:
            vision_hidden_states = vision_tower.patch_embed(pixel_values, grid_thw=image_grid_thw)
            _, image_patch_counts = get_clip_counts(image_grid_thw, kernel_height, kernel_width)
            all_patch_counts.extend(image_patch_counts)
            if input_ids is not None:
                all_spans.append(find_spans(input_ids, self.config.image_token_id))

        if pixel_values_videos is not None and video_grid_thw is not None:
            video_hidden = vision_tower.patch_embed(pixel_values_videos, grid_thw=video_grid_thw)
            _, video_patch_counts = get_clip_counts(video_grid_thw, kernel_height, kernel_width)
            all_patch_counts.extend(video_patch_counts)
            video_token_id = getattr(self.config, "video_token_id", None)
            if video_token_id is not None and input_ids is not None:
                all_spans.append(find_spans(input_ids, video_token_id))
            vision_hidden_states = (
                video_hidden
                if vision_hidden_states is None
                else torch.cat([vision_hidden_states, video_hidden], dim=0)
            )

        if vision_hidden_states is not None:
            grids = [grid for grid in (image_grid_thw, video_grid_thw) if grid is not None]
            combined_grid = torch.cat(grids, dim=0)
            vision_position_ids = get_vision_position_ids(combined_grid, spatial_merge_size=1, kwargs=kwargs)
            vision_position_ids = vision_position_ids.transpose(0, 1).flip(0)
            vision_position_embeddings = vision_tower.rotary_emb(vision_hidden_states, vision_position_ids)
            vision_cu_seqlens, vision_max_seqlen = get_vision_attention_seqlens(
                combined_grid, vision_config, merge_temporal=True, kwargs=kwargs
            )
            vision_residual = vision_hidden_states.new_zeros(
                vision_hidden_states.size(0), self.num_attn_res_blocks, vision_hidden_states.size(-1)
            )
            vision_prefix_sum = vision_hidden_states
            vision_hidden_states = None

            for layer in self.blocks[0].vision_layers:
                vision_hidden_states, vision_prefix_sum, vision_residual = layer(
                    vision_hidden_states,
                    vision_residual,
                    vision_prefix_sum,
                    vision_cu_seqlens,
                    vision_position_embeddings,
                    max_seqlen=vision_max_seqlen,
                    **kwargs,
                )

            patch_offset = 0
            if pixel_values is not None and image_grid_thw is not None and input_ids is not None:
                image_patch_count = sum(image_patch_counts)
                pooled_images = vision_tower.temporal_patch_merger(
                    vision_hidden_states[:image_patch_count], image_grid_thw
                )
                projected_images = self.mm_projector(pooled_images).squeeze(1).to(dtype=embed_dtype)
                image_placeholder_mask = (input_ids == self.config.image_token_id).unsqueeze(-1)
                inputs_embeds = inputs_embeds.masked_scatter(image_placeholder_mask, projected_images)
                patch_offset = image_patch_count

            if pixel_values_videos is not None and video_grid_thw is not None and input_ids is not None:
                video_patch_count = sum(video_patch_counts)
                pooled_videos = vision_tower.temporal_patch_merger(
                    vision_hidden_states[patch_offset : patch_offset + video_patch_count], video_grid_thw
                )
                projected_videos = self.mm_projector(pooled_videos).squeeze(1).to(dtype=embed_dtype)
                video_token_id = getattr(self.config, "video_token_id", None)
                if video_token_id is not None:
                    video_placeholder_mask = (input_ids == video_token_id).unsqueeze(-1)
                    inputs_embeds = inputs_embeds.masked_scatter(video_placeholder_mask, projected_videos)

            if input_ids is not None:
                vision_evidence_mask, vision_guidance_mask, vision_patch_to_row = self.get_cross_mask(
                    input_ids, all_patch_counts, all_spans, sequence_length, embed_dtype, device
                )

        language_model = self.language_model
        num_streams = self.config.text_config.hc_mult
        hidden_states = inputs_embeds.unsqueeze(2).expand(-1, -1, num_streams, -1).contiguous()
        position_embeddings = {
            "main": language_model.rotary_emb(inputs_embeds, position_ids=position_ids, layer_type="main"),
            "compress": language_model.rotary_emb(inputs_embeds, position_ids=position_ids, layer_type="compress"),
        }
        block_residual = hidden_states.new_zeros(
            *hidden_states.shape[:2], num_streams, self.num_attn_res_blocks, hidden_states.size(-1)
        )
        prefix_sum = hidden_states
        hidden_states = None
        residual = block_residual

        if isinstance(attention_mask, dict):
            causal_mask = next(iter(attention_mask.values()))
        else:
            causal_mask = create_sliding_window_causal_mask(
                config=self.config.text_config,
                inputs_embeds=inputs_embeds,
                attention_mask=attention_mask,
                past_key_values=past_key_values,
                position_ids=position_ids,
            )

        output_hidden_states = kwargs.get("output_hidden_states", self.config.output_hidden_states)
        all_hidden_states = (inputs_embeds,) if output_hidden_states else ()
        for block_index, block in enumerate(self.blocks):
            block_inputs = {
                "hidden_states": hidden_states,
                "residual": residual,
                "prefix_sum": prefix_sum,
                "input_ids": input_ids,
                "position_embeddings": position_embeddings,
                "position_ids": position_ids,
                "attention_mask": causal_mask,
                "past_key_values": past_key_values,
                "vision_hidden_states": vision_hidden_states,
                "vision_prefix_sum": vision_prefix_sum,
                "vision_residual": vision_residual,
                "vision_cu_seqlens": vision_cu_seqlens,
                "vision_position_embeddings": vision_position_embeddings,
                "vision_max_seqlen": vision_max_seqlen,
                "evidence_mask": vision_evidence_mask,
                "num_attn_res_blocks": self.num_attn_res_blocks,
                "run_vision_layers": (block_index > 0),
            }
            if isinstance(block, ShensiVlCrossBlock):
                block_inputs.update(guidance_mask=vision_guidance_mask, vision_patch_to_row=vision_patch_to_row)
            (
                hidden_states,
                prefix_sum,
                residual,
                vision_hidden_states,
                vision_prefix_sum,
                vision_residual,
                layer_hidden_states,
            ) = block(
                **block_inputs,
                **{
                    **kwargs,
                    "output_hidden_states": output_hidden_states,
                    "output_attentions": kwargs.get("output_attentions", self.config.output_attentions),
                },
            )
            if output_hidden_states:
                all_hidden_states += tuple(
                    language_model.norm(language_model.hc_head(state)) for state in layer_hidden_states
                )

        hidden_states = language_model.norm(language_model.hc_head(hidden_states))
        return ShensiVlModelOutputWithPast(
            last_hidden_state=hidden_states,
            past_key_values=past_key_values,
            hidden_states=all_hidden_states or None,
        )

    def _resize_token_embeddings(self, new_num_tokens, pad_to_multiple_of=None, mean_resizing=True):
        embeddings = super()._resize_token_embeddings(new_num_tokens, pad_to_multiple_of, mean_resizing)
        self.language_model._resize_token_embeddings(new_num_tokens, pad_to_multiple_of, mean_resizing)
        return embeddings

    def get_cross_mask(
        self,
        input_ids: torch.LongTensor,
        all_patch_counts: list[int],
        all_spans: list[list[tuple[int, int]]],
        sequence_length: int,
        dtype: torch.dtype,
        device: torch.device,
    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        r"""
        Builds the cross-modal attention masks over the merged patch set.

        Clip ids increment in packing order (all image clips of row 0..B-1, then all video
        clips), matching the patch order inside the packed vision sequence.

        Args:
            input_ids (`torch.LongTensor` of shape `(batch_size, sequence_length)`):
                Input token ids.
            all_patch_counts (`list[int]`):
                Per clip, the number of packed patches (KV rows).
            all_spans (`list[list[tuple[int, int]]]`):
                Per media modal (image, then video), the `(start, length)` placeholder spans
                found in each input row.
            sequence_length (`int`):
                The input sequence length.
            dtype (`torch.dtype`):
                Output mask dtype.
            device (`torch.device`):
                Output mask device.

        Returns:
            `tuple[torch.Tensor, torch.Tensor, torch.Tensor]`: `(evidence_mask, guidance_mask,
            patch_to_row)`, where `evidence_mask` is causal (`(batch_size, 1, seq_len, total_kv)`),
            `guidance_mask` matches each patch to its own clip (`(batch_size, 1, num_patches,
            seq_len)`), and `patch_to_row` is the batch row owning each packed patch.
        """
        number_of_clips = len(all_patch_counts)
        batch_size = input_ids.shape[0]
        media_spans = [[] for _ in range(batch_size)]  # per row: (start, length, global_clip_id)
        kv_clip_ids = torch.full((batch_size, sequence_length), -1, dtype=torch.long, device=device)
        clip_to_row = torch.full((number_of_clips,), -1, dtype=torch.long, device=device)
        clip_cursor = 0
        for span_group in all_spans:
            for row_index, row_spans in enumerate(span_group):
                for start, length in row_spans:
                    media_spans[row_index].append((start, length, clip_cursor))
                    kv_clip_ids[row_index, start : start + length] = clip_cursor
                    clip_to_row[clip_cursor] = row_index
                    clip_cursor += 1

        min_value = torch.finfo(dtype).min
        total_kv = sum(all_patch_counts)
        evidence_mask = torch.full((batch_size, sequence_length, total_kv), min_value, dtype=dtype, device=device)
        offsets = [0]
        for count in all_patch_counts:
            offsets.append(offsets[-1] + count)
        for row_index, segments in enumerate(media_spans):
            for start, _, clip_id in segments:
                evidence_mask[row_index, start:, offsets[clip_id] : offsets[clip_id] + all_patch_counts[clip_id]] = 0.0
        evidence_mask = evidence_mask.unsqueeze(1)
        full_row_visible = (evidence_mask != min_value).any(dim=-1, keepdim=True).type_as(evidence_mask)
        evidence_mask = evidence_mask * full_row_visible

        patch_clip_ids = torch.arange(number_of_clips, device=device).repeat_interleave(
            torch.tensor(all_patch_counts, device=device)
        )
        patch_to_row = clip_to_row[patch_clip_ids]
        same_clip = patch_clip_ids[None, :, None] == kv_clip_ids[:, None, :]
        guidance_mask = torch.where(same_clip, 0.0, min_value).to(device=device, dtype=dtype).unsqueeze(1)
        return evidence_mask, guidance_mask, patch_to_row


@auto_docstring(
    custom_intro="""
    Base class for ShensiVl causal language model (or autoregressive) outputs.
    """
)
@dataclass
class ShensiVlCausalLMOutputWithPast(ModelOutput):
    r"""
    loss (`torch.FloatTensor` of shape `(1,)`, *optional*, returned when `labels` is provided):
        Language modeling loss (for next-token prediction).
    logits (`torch.FloatTensor` of shape `(batch_size, sequence_length, config.vocab_size)`):
        Prediction scores of the language modeling head (scores for each vocabulary token before SoftMax).
    past_key_values (`Cache`, *optional*, returned when `use_cache=True` is passed or when `config.use_cache=True`):
        It is a [`~cache_utils.Cache`] instance. For more details, see our [kv cache guide](https://huggingface.co/docs/transformers/en/kv_cache).

        Contains pre-computed hidden-states (key and values in the self-attention blocks) that can be used (see
        `past_key_values` input) to speed up sequential decoding.
    image_hidden_states (`torch.FloatTensor`, *optional*):
        A `torch.FloatTensor` of size `(batch_size, num_images, sequence_length, hidden_size)`.
        image_hidden_states of the model produced by the vision encoder and after projecting the last hidden state.
    """

    loss: torch.FloatTensor | None = None
    logits: torch.FloatTensor | None = None
    past_key_values: Cache | None = None
    hidden_states: tuple[torch.FloatTensor] | None = None
    attentions: tuple[torch.FloatTensor] | None = None
    image_hidden_states: torch.FloatTensor | None = None
    aux_loss: torch.FloatTensor | None = None


def load_balancing_loss_func(
    gate_logits: torch.Tensor | tuple[torch.Tensor] | None,
    num_experts: int | None = None,
    top_k=2,
    attention_mask: torch.Tensor | None = None,
) -> torch.Tensor | int:
    r"""
    Computes auxiliary load balancing loss as in Switch Transformer - implemented in Pytorch.

    See Switch Transformer (https://huggingface.co/papers/2101.03961) for more details. This function implements the loss
    function presented in equations (4) - (6) of the paper. It aims at penalizing cases where the routing between
    experts is too unbalanced.

    Args:
        gate_logits:
            Logits from the `gate`, should be a tuple of model.config.num_hidden_layers tensors of
            shape [batch_size X sequence_length, num_experts].
        num_experts:
            Number of experts
        top_k:
            The number of experts to route per-token, can be also interpreted as the `top-k` routing
            parameter.
        attention_mask (`torch.Tensor`, *optional*):
            The attention_mask used in forward function
            shape [batch_size X sequence_length] if not None.

    Returns:
        The auxiliary loss.
    """
    if gate_logits is None or not isinstance(gate_logits, tuple):
        return 0

    # Accumulate assignment counts and probability sums layer by layer, normalizing at the end,
    # so peak memory stays O(seq_len * num_experts) regardless of the number of layers.
    compute_device = gate_logits[0].device
    tokens_per_expert_sum = torch.zeros(num_experts, dtype=torch.float32, device=compute_device)
    router_prob_sum = torch.zeros(num_experts, dtype=torch.float32, device=compute_device)
    total_rows = 0.0

    if attention_mask is not None:
        # The same flat mask applies to every layer's [batch_size * sequence_length] rows.
        flat_mask = attention_mask.reshape(-1).to(device=compute_device, dtype=torch.float32)

    for layer_gate in gate_logits:
        routing_weights = torch.nn.functional.softmax(layer_gate.to(compute_device), dim=-1)
        _, selected_experts = torch.topk(routing_weights, top_k, dim=-1)
        if attention_mask is None:
            # Count of top-k assignments per expert
            tokens_per_expert_sum = (
                tokens_per_expert_sum + torch.bincount(selected_experts.reshape(-1), minlength=num_experts).float()
            )
            # Sum of routing probabilities per expert
            router_prob_sum = router_prob_sum + routing_weights.float().sum(dim=0)
            total_rows = total_rows + routing_weights.shape[0]
        else:
            # Same reductions, weighted by the attention mask to exclude padding tokens
            tokens_per_expert_sum = tokens_per_expert_sum + torch.zeros(
                num_experts, dtype=torch.float32, device=compute_device
            ).scatter_add_(0, selected_experts.reshape(-1), flat_mask.repeat_interleave(top_k))
            router_prob_sum = router_prob_sum + (routing_weights.float() * flat_mask.unsqueeze(-1)).sum(dim=0)
            total_rows = total_rows + flat_mask.sum()

    tokens_per_expert = tokens_per_expert_sum / total_rows
    router_prob_per_expert = router_prob_sum / total_rows

    overall_loss = torch.sum(tokens_per_expert * router_prob_per_expert.unsqueeze(0))
    return overall_loss * num_experts


def erc_loss_func(
    coupling_matrix: torch.Tensor | None,
    alpha: float = 1.0,
) -> torch.Tensor | int:
    r"""
    Computes auxiliary expert-router coupling (ERC) loss as in arXiv 2512.23447 - implemented in Pytorch.

    See arXiv 2512.23447 (https://arxiv.org/abs/2512.23447) for more details. This function implements the loss
    function presented in Figure 8 (pseudocode, `erc_loss` method) of the paper, given the coupling matrix `M`
    with `M[i, j]` the activation norm of expert `j` given the proxy token of expert `i`. For all `i != j`, a
    penalty is imposed wherever the off-diagonal elements `M[i, j]` or `M[j, i]` exceed `alpha * M[i, i]`, where
    `alpha` is a scalar hyperparameter:

    Args:
        coupling_matrix:
            The coupling matrix `M` of shape [n_experts, n_experts], with `M[i, j]` the activation
            norm of expert `j` given the proxy token of expert `i`.
        alpha (`float`, *optional*):
            The scalar hyperparameter controlling the specialization level: an off-diagonal
            activation `M[i, j]` is penalized once it exceeds `alpha * M[i, i]`.

    Returns:
        The expert-router coupling loss.
    """
    if coupling_matrix is None:
        return 0

    M = coupling_matrix

    # Penalize the off-diagonal rows that exceed alpha times the diagonal
    row_diff = M - alpha * torch.diag(M).unsqueeze(1)
    row_diff_clamped = torch.clamp(row_diff, min=0.0)

    # Penalize the off-diagonal columns that exceed alpha times the diagonal
    col_diff = M - alpha * torch.diag(M).unsqueeze(0)
    col_diff_clamped = torch.clamp(col_diff, min=0.0)

    mask = torch.ones_like(M) - torch.eye(M.size(0), device=M.device)
    total_diff = (row_diff_clamped + col_diff_clamped) * mask

    return total_diff.mean()


def compute_loss_func(
    gate_logits: torch.Tensor | tuple[torch.Tensor] | None,
    num_experts: int | None = None,
    top_k=2,
    attention_mask: torch.Tensor | None = None,
    sharing_layers: tuple[list[int] | None, ...] | None = None,
    coupling_matrices: tuple[torch.Tensor | None, ...] | None = None,
    alpha: float = 1.0,
) -> tuple[torch.Tensor | int, torch.Tensor | int]:
    aux_loss = 0
    if gate_logits is not None and isinstance(gate_logits, tuple) and sharing_layers:
        for layer_ids in sharing_layers:
            if layer_ids is None:
                continue
            subset = tuple(gate_logits[pos] for pos in layer_ids)
            aux_loss += load_balancing_loss_func(subset, num_experts, top_k, attention_mask)

    erc_loss = 0
    if coupling_matrices:
        for coupling_matrix in coupling_matrices:
            if coupling_matrix is None:
                continue
            erc_loss += erc_loss_func(coupling_matrix, alpha=alpha)

    return aux_loss, erc_loss


@auto_docstring
class ShensiVlForConditionalGeneration(ShensiVlPreTrainedModel, GenerationMixin):
    _tied_weights_keys = {"lm_head.weight": "model.language_model.embed_tokens.weight"}
    # Reference: fix gemma3 grad acc #37208
    accepts_loss_kwargs = False

    def __init__(self, config):
        super().__init__(config)
        self.model = ShensiVlModel(config)
        self.lm_head = nn.Linear(config.text_config.hidden_size, config.text_config.vocab_size, bias=False)

        self.post_init()

    @auto_docstring
    def get_video_features(
        self,
        pixel_values_videos: torch.FloatTensor,
        video_grid_thw: torch.LongTensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        pixel_values_videos (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
            The tensors corresponding to the input videos.
        """
        return self.model.get_video_features(pixel_values_videos, video_grid_thw, **kwargs)

    @auto_docstring
    def get_image_features(
        self,
        pixel_values: torch.FloatTensor,
        image_grid_thw: torch.LongTensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        pixel_values (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
            The tensors corresponding to the input images.
        """
        return self.model.get_image_features(pixel_values, image_grid_thw, **kwargs)

    @can_return_tuple
    @auto_docstring
    def forward(
        self,
        input_ids: torch.LongTensor | None = None,
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        past_key_values: Cache | None = None,
        inputs_embeds: torch.FloatTensor | None = None,
        labels: torch.LongTensor | None = None,
        use_cache: bool | None = None,
        pixel_values: torch.Tensor | None = None,
        image_grid_thw: torch.LongTensor | None = None,
        pixel_values_videos: torch.Tensor | None = None,
        video_grid_thw: torch.LongTensor | None = None,
        logits_to_keep: int | torch.Tensor = 0,
        output_router_logits: bool | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | ShensiVlCausalLMOutputWithPast:
        r"""
        Example:

        ```python
        >>> from transformers import AutoProcessor, ShensiVlForConditionalGeneration

        >>> model = ShensiVlForConditionalGeneration.from_pretrained("moonshotai/Kimi-K2.6")
        >>> processor = AutoProcessor.from_pretrained("moonshotai/Kimi-K2.6")

        >>> messages = [
            {
                "role": "user",
                "content": [
                    {
                        "type": "image",
                        "image": "https://huggingface.co/datasets/huggingface/documentation-images/resolve/main/pipeline-cat-chonk.jpeg",
                    },
                    {"type": "text", "text": "Describe the image."},
                ],
            }
        ]

        >>> inputs = processor.apply_chat_template(
            messages,
            tokenize=True,
            add_generation_prompt=True,
            return_dict=True,
            return_tensors="pt",
        )

        >>> # Generate
        >>> generated_ids = model.generate(**inputs, max_new_tokens=1024)
        >>> generated_ids_trimmed = [out_ids[len(in_ids) :] for in_ids, out_ids in zip(inputs.input_ids, generated_ids)]
        >>> output_text = processor.batch_decode(generated_ids_trimmed, skip_special_tokens=True, clean_up_tokenization_spaces=False)[0]
        >>> print(output_text)
        ```
        """
        output_router_logits = (
            output_router_logits if output_router_logits is not None else self.config.text_config.output_router_logits
        )

        outputs: ShensiVlModelOutputWithPast = self.model(
            input_ids=input_ids,
            pixel_values=pixel_values,
            image_grid_thw=image_grid_thw,
            pixel_values_videos=pixel_values_videos,
            video_grid_thw=video_grid_thw,
            position_ids=position_ids,
            attention_mask=attention_mask,
            past_key_values=past_key_values,
            inputs_embeds=inputs_embeds,
            use_cache=use_cache,
            output_router_logits=output_router_logits,
            output_coupling_matrix=output_router_logits,
            output_sharing_layers=output_router_logits,
            **kwargs,
        )

        hidden_states = outputs.last_hidden_state
        # Only compute necessary logits, and do not upcast them to float if we are not computing the loss
        slice_indices = slice(-logits_to_keep, None) if isinstance(logits_to_keep, int) else logits_to_keep
        logits = self.lm_head(hidden_states[:, slice_indices, :])

        loss = None
        if labels is not None:
            loss = self.loss_function(
                logits=logits, labels=labels, vocab_size=self.config.text_config.vocab_size, **kwargs
            )

        aux_loss = None
        if output_router_logits and labels is not None:
            aux_loss, erc_loss = compute_loss_func(
                outputs.router_logits,
                self.config.text_config.n_routed_experts,
                self.config.text_config.num_experts_per_tok,
                attention_mask,
                getattr(outputs, "sharing_layers", None),
                getattr(outputs, "coupling_matrix", None),
                self.config.text_config.erc_loss_alpha,
            )
            if aux_loss != 0:
                loss = loss + self.config.text_config.router_aux_loss_coef * aux_loss.to(loss.device)
            if erc_loss != 0:
                loss = loss + self.config.text_config.erc_loss_coef * erc_loss.to(loss.device)

        return ShensiVlCausalLMOutputWithPast(
            loss=loss,
            aux_loss=aux_loss,
            logits=logits,
            past_key_values=outputs.past_key_values,
            hidden_states=outputs.hidden_states,
            attentions=outputs.attentions,
        )

    def _resize_token_embeddings(self, new_num_tokens, pad_to_multiple_of=None, mean_resizing=True):
        embeddings = super()._resize_token_embeddings(new_num_tokens, pad_to_multiple_of, mean_resizing)
        self.model._resize_token_embeddings(new_num_tokens, pad_to_multiple_of, mean_resizing)
        return embeddings


__all__ = ["ShensiVlForConditionalGeneration", "ShensiVlModel", "ShensiVlPreTrainedModel", "ShensiVlVisionModel"]
